.bkp-tiers {
  /* re-theme: override these four */
  --bkp-tiers-bg: oklch(96.4% 0.007 80);
  --bkp-tiers-ink: oklch(19% 0.012 60);
  --bkp-tiers-accent: oklch(66% 0.195 38);
  --bkp-tiers-card: oklch(99.4% 0.003 80);

  --bkp-tiers-muted: color-mix(in oklch, var(--bkp-tiers-ink) 58%, var(--bkp-tiers-bg));
  --bkp-tiers-line: color-mix(in oklch, var(--bkp-tiers-ink) 12%, transparent);
  --bkp-tiers-line-2: color-mix(in oklch, var(--bkp-tiers-ink) 22%, transparent);
  --bkp-tiers-out: cubic-bezier(.16, 1, .3, 1);
  --bkp-tiers-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkp-tiers-lh: 1.2em;

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkp-tiers-bg);
  color: var(--bkp-tiers-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, fieldset, legend) { margin: 0; padding: 0; border: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; }
}
.bkp-tiers-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-tiers-in { max-width: 1180px; margin-inline: auto; padding: clamp(36px, 6.5cqi, 84px) clamp(16px, 4cqi, 48px); }

/* ---------- header ---------- */
.bkp-tiers-head { display: grid; gap: 14px; grid-template-areas: "brand" "title" "lede"; }
.bkp-tiers-brand {
  grid-area: brand; display: flex; align-items: center; gap: 8px; font-weight: 650; letter-spacing: -.01em;
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & span { margin-left: 4px; padding: 2px 8px; border: 1px solid var(--bkp-tiers-line-2); border-radius: 99px; font: 500 11px/1.4 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; color: var(--bkp-tiers-muted); }
}
.bkp-tiers-title {
  grid-area: title; font-size: clamp(34px, 5.6cqi, 66px); font-weight: 700; line-height: .98; letter-spacing: -.042em; text-wrap: balance;
  & span { color: var(--bkp-tiers-muted); }
}
.bkp-tiers-lede { grid-area: lede; max-width: 46ch; font-size: clamp(15px, 1.45cqi, 17px); color: var(--bkp-tiers-muted); text-wrap: pretty; }
@container (width >= 860px) {
  .bkp-tiers-head { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); grid-template-areas: "brand brand" "title lede"; column-gap: 6cqi; align-items: end; }
  .bkp-tiers-lede { padding-bottom: .4em; }
}

/* ---------- segmented controls ---------- */
.bkp-tiers-controls { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; margin-top: clamp(26px, 4cqi, 44px); }
.bkp-tiers-seg {
  --n: 2; --k: 0;
  position: relative; display: inline-grid; grid-template-columns: repeat(var(--n), 1fr);
  padding: 4px; border-radius: 99px; background: var(--bkp-tiers-card); box-shadow: inset 0 0 0 1px var(--bkp-tiers-line-2);
  & label { position: relative; z-index: 1; display: grid; place-items: center; cursor: pointer; border-radius: 99px; }
  & label > span { display: flex; align-items: center; gap: 8px; padding: 9px 18px; font-weight: 600; white-space: nowrap; transition: color .3s var(--bkp-tiers-out); }
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & label:has(input:checked) > span { color: var(--bkp-tiers-bg); }
  & label:has(input:focus-visible) { outline: 2px solid var(--bkp-tiers-accent); outline-offset: 2px; }
  & label:not(:has(input:checked)):hover > span { color: var(--bkp-tiers-accent); }
}
.bkp-tiers-thumb {
  position: absolute; inset: 4px auto 4px 4px; width: calc((100% - 8px) / var(--n)); border-radius: 99px; background: var(--bkp-tiers-ink);
  translate: calc(var(--k) * 100%) 0; transition: translate .55s var(--bkp-tiers-spring);
}
.bkp-tiers-period:has(input[value="year"]:checked) { --k: 1; }
.bkp-tiers-cur { --n: 3; font: 500 12px/1 ui-monospace, Menlo, monospace; letter-spacing: .06em;
  & label > span { padding: 8px 14px; }
}
.bkp-tiers-cur:has(input[value="eur"]:checked) { --k: 1; }
.bkp-tiers-cur:has(input[value="gbp"]:checked) { --k: 2; }
.bkp-tiers-save {
  padding: 3px 7px; border-radius: 99px; font: 700 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .02em;
  background: color-mix(in oklch, var(--bkp-tiers-accent) 18%, transparent); color: color-mix(in oklch, var(--bkp-tiers-accent) 70%, var(--bkp-tiers-ink));
  transition: background-color .3s, color .3s;
}
.bkp-tiers-period:has(input[value="year"]:checked) .bkp-tiers-save { background: var(--bkp-tiers-accent); color: var(--bkp-tiers-ink); }

/* ---------- cards on a shared subgrid ---------- */
.bkp-tiers-grid { display: grid; grid-template-columns: minmax(0, 1fr); row-gap: 14px; margin-top: 18px; }
@container (width >= 760px) { .bkp-tiers-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: 14px; } }
.bkp-tiers-card {
  position: relative; grid-row: span 5; display: grid; grid-template-rows: subgrid; row-gap: 0;
  padding: clamp(20px, 2.3cqi, 28px); border-radius: 16px; background: var(--bkp-tiers-card);
  box-shadow: inset 0 0 0 1px var(--bkp-tiers-line), 0 1px 0 var(--bkp-tiers-line);
  transition: opacity .6s var(--bkp-tiers-out) calc(var(--c) * 90ms), translate .9s var(--bkp-tiers-out) calc(var(--c) * 90ms), transform .45s var(--bkp-tiers-out), box-shadow .45s var(--bkp-tiers-out);
  @starting-style { opacity: 0; translate: 0 24px; }
  &:hover { transform: translateY(-4px); box-shadow: inset 0 0 0 1px var(--bkp-tiers-line-2), 0 18px 40px -22px color-mix(in oklch, var(--bkp-tiers-ink) 45%, transparent); }
}
.bkp-tiers-pick {
  --bkp-tiers-card: var(--bkp-tiers-ink);
  color: var(--bkp-tiers-bg);
  --bkp-tiers-muted: color-mix(in oklch, var(--bkp-tiers-bg) 64%, var(--bkp-tiers-ink));
  --bkp-tiers-line: color-mix(in oklch, var(--bkp-tiers-bg) 14%, transparent);
  --bkp-tiers-line-2: color-mix(in oklch, var(--bkp-tiers-bg) 26%, transparent);
}
.bkp-tiers-flag {
  position: absolute; top: clamp(20px, 2.3cqi, 28px); right: clamp(20px, 2.3cqi, 28px);
  padding: 5px 10px; border-radius: 99px; background: var(--bkp-tiers-accent); color: var(--bkp-tiers-ink);
  font: 700 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; text-transform: uppercase;
}
.bkp-tiers-top { padding-bottom: 22px; }
.bkp-tiers-name { font-size: 20px; font-weight: 700; letter-spacing: -.02em; }
.bkp-tiers-blurb { margin-top: 6px; max-width: 30ch; color: var(--bkp-tiers-muted); text-wrap: pretty; }

/* ---------- odometer price ---------- */
.bkp-tiers-price { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 6px; padding-top: 2px; border-top: 1px solid var(--bkp-tiers-line); padding-block-start: 18px; }
.bkp-tiers-odo {
  display: inline-flex; height: var(--bkp-tiers-lh); line-height: var(--bkp-tiers-lh);
  font-size: clamp(48px, 5.4cqi, 64px); font-weight: 680; letter-spacing: -.04em; font-variant-numeric: tabular-nums;
  mask-image: linear-gradient(to bottom, transparent, #000 13%, #000 87%, transparent);
}
.bkp-tiers-slot {
  display: block; width: 1ch; margin-right: -.04em;
  transition: width .6s var(--bkp-tiers-out) calc(var(--c, 0) * 70ms), opacity .4s var(--bkp-tiers-out);
  &[data-off] { width: 0; margin-right: 0; opacity: 0; }
}
.bkp-tiers-sym { width: auto; margin-right: .07em; font-size: .62em; font-weight: 600; line-height: calc(var(--bkp-tiers-lh) / .62); height: 100%;
  & .bkp-tiers-strip { --step: calc(var(--bkp-tiers-lh) / .62); translate: 0 .18em; }
  & .bkp-tiers-strip > span { text-align: right; }
}
.bkp-tiers-strip {
  --step: var(--bkp-tiers-lh);
  display: flex; flex-direction: column;
  transform: translateY(calc(var(--d, 0) * var(--step) * -1));
  transition: transform 1.05s var(--bkp-tiers-spring) calc(var(--c, 0) * 70ms + var(--i, 0) * 45ms);
  & > span { display: block; height: var(--step); }
  @starting-style { transform: translateY(0); }
}
.bkp-tiers-unit { font-weight: 600; color: var(--bkp-tiers-muted); }
.bkp-tiers-was {
  position: relative; margin-left: 4px; font: 500 15px/1 system-ui, sans-serif; text-decoration: none; color: var(--bkp-tiers-muted); font-variant-numeric: tabular-nums;
  opacity: 0; transition: opacity .35s var(--bkp-tiers-out);
  &::after { content: ""; position: absolute; left: -2px; right: -2px; top: 52%; height: 1.5px; background: var(--bkp-tiers-accent); transform: scaleX(0); transform-origin: left; transition: transform .45s var(--bkp-tiers-out) .15s; }
}
.bkp-tiers:has(.bkp-tiers-period input[value="year"]:checked) .bkp-tiers-was:not(:empty) { opacity: 1; &::after { transform: scaleX(1); } }
.bkp-tiers-bill { padding: 8px 0 20px; font-size: 13.5px; color: var(--bkp-tiers-muted); font-variant-numeric: tabular-nums; min-height: 3.4em; }

/* ---------- CTA ---------- */
.bkp-tiers-cta {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 46px; padding: 0 16px;
  border: 0; border-radius: 11px; cursor: pointer; font-weight: 650;
  background: var(--bkp-tiers-ink); color: var(--bkp-tiers-bg);
  transition: transform .2s var(--bkp-tiers-out), background-color .25s, box-shadow .25s;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; transition: transform .35s var(--bkp-tiers-spring); }
  &:hover svg { transform: translateX(3px); }
  &:active { transform: scale(.98); }
  &:focus-visible { outline: 2px solid var(--bkp-tiers-accent); outline-offset: 3px; }
  &[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--bkp-tiers-card), 0 0 0 4px var(--bkp-tiers-accent); }
}
.bkp-tiers-card:first-child .bkp-tiers-cta { background: transparent; color: var(--bkp-tiers-ink); box-shadow: inset 0 0 0 1.5px var(--bkp-tiers-line-2);
  &:hover { box-shadow: inset 0 0 0 1.5px var(--bkp-tiers-ink); }
  &[aria-pressed="true"] { box-shadow: inset 0 0 0 1.5px var(--bkp-tiers-ink), 0 0 0 2px var(--bkp-tiers-card), 0 0 0 4px var(--bkp-tiers-accent); }
}
.bkp-tiers-pick .bkp-tiers-cta { background: var(--bkp-tiers-accent); color: var(--bkp-tiers-ink); &:hover { background: color-mix(in oklch, var(--bkp-tiers-accent) 86%, white); } }

/* ---------- features ---------- */
.bkp-tiers-feat {
  display: grid; align-content: start; gap: 10px; margin-top: 22px; padding-top: 20px; border-top: 1px solid var(--bkp-tiers-line);
  & li { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 10px; align-items: start; font-size: 14.5px; text-wrap: pretty; }
  & svg { width: 18px; height: 18px; margin-top: 1px; fill: none; stroke: var(--bkp-tiers-accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & .bkp-tiers-plus { display: block; font: 600 11px/1.6 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; color: var(--bkp-tiers-muted); }
}

/* ---------- enterprise strip ---------- */
.bkp-tiers-ent {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 24px; margin-top: 14px;
  padding: 18px clamp(20px, 2.3cqi, 28px); border-radius: 16px; box-shadow: inset 0 0 0 1px var(--bkp-tiers-line-2);
  & p { max-width: 70ch; color: var(--bkp-tiers-muted); text-wrap: pretty; }
  & b { margin-right: 6px; color: var(--bkp-tiers-ink); font-weight: 700; }
}
.bkp-tiers-copy {
  display: inline-flex; align-items: center; gap: 8px; padding: 9px 14px; border: 0; border-radius: 99px; cursor: pointer;
  background: color-mix(in oklch, var(--bkp-tiers-ink) 6%, transparent); font: 500 13px/1 ui-monospace, Menlo, monospace;
  transition: background-color .25s;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { background: color-mix(in oklch, var(--bkp-tiers-ink) 11%, transparent); }
  &:focus-visible { outline: 2px solid var(--bkp-tiers-accent); outline-offset: 2px; }
  &[data-done] { background: color-mix(in oklch, var(--bkp-tiers-accent) 22%, transparent); }
}

@container (width < 520px) {
  .bkp-tiers-controls { justify-content: flex-start; }
  .bkp-tiers-period { flex: 1 1 100%; display: grid; }
  .bkp-tiers-seg label > span { padding-inline: 12px; }
  .bkp-tiers-flag { position: static; justify-self: start; margin-bottom: 14px; grid-row: 1; }
  .bkp-tiers-pick { grid-row: span 6; }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-tiers-card, .bkp-tiers-strip, .bkp-tiers-slot, .bkp-tiers-thumb, .bkp-tiers-was::after { transition: none; }
  .bkp-tiers-card:hover { transform: none; }
  .bkp-tiers-was { transition: opacity .2s linear; }
  .bkp-tiers-cta svg { transition: none; }
}

