const CODES = ['usd', 'eur', 'gbp'];
const SYM = { usd: '$', eur: '€', gbp: '£' };
const uid = Math.random().toString(36).slice(2, 8);
root.querySelectorAll('input[type="radio"]').forEach((i) => { i.name = i.name + '-' + uid; });

const cards = [...root.querySelectorAll('.bkp-tiers-card')];
const live = root.querySelector('[data-live]');
const fmts = {};
const money = (v, c) => (fmts[c] ||= new Intl.NumberFormat('en', { style: 'currency', currency: c.toUpperCase(), maximumFractionDigits: 0 })).format(v);
const strip = (chars) => '<span class="bkp-tiers-strip">' + chars.map((ch) => '<span>' + ch + '</span>').join('') + '</span>';

/* Build the odometer: one symbol reel and three digit reels per price. */
cards.forEach((card, ci) => {
  const odo = card.querySelector('.bkp-tiers-odo');
  const sym = document.createElement('span');
  sym.className = 'bkp-tiers-slot bkp-tiers-sym';
  sym.innerHTML = strip(CODES.map((c) => SYM[c]));
  odo.append(sym);
  for (let i = 0; i < 3; i++) {
    const s = document.createElement('span');
    s.className = 'bkp-tiers-slot';
    s.style.setProperty('--i', i + 1);
    s.innerHTML = strip('0123456789'.split(''));
    odo.append(s);
  }
  card.querySelector('.bkp-tiers-cta span').dataset.label = card.querySelector('.bkp-tiers-cta span').textContent;
});

const checked = (sel) => root.querySelector(sel + ' input:checked').value;

function render(announce) {
  const cur = checked('.bkp-tiers-cur');
  const yearly = checked('.bkp-tiers-period') === 'year';
  cards.forEach((card) => {
    const [m, y] = JSON.parse(card.dataset.price)[cur];
    const v = yearly ? y : m;
    const slots = card.querySelectorAll('.bkp-tiers-slot');
    slots[0].querySelector('.bkp-tiers-strip').style.setProperty('--d', CODES.indexOf(cur));
    const digits = String(v).padStart(3, ' ');
    for (let i = 0; i < 3; i++) {
      const slot = slots[i + 1];
      if (digits[i] === ' ') { slot.dataset.off = ''; continue; }
      delete slot.dataset.off;
      slot.querySelector('.bkp-tiers-strip').style.setProperty('--d', +digits[i]);
    }
    card.querySelector('.bkp-tiers-say').textContent = money(v, cur) + ' per month';
    card.querySelector('.bkp-tiers-was').textContent = yearly && m > 0 ? money(m, cur) : '';
    const bill = card.querySelector('.bkp-tiers-bill');
    const text = m === 0 ? 'Free forever · no card needed'
      : yearly ? money(y * 12, cur) + ' billed yearly · you save ' + money((m - y) * 12, cur)
      : 'Billed monthly · cancel anytime';
    if (bill.textContent !== text) {
      bill.textContent = text;
      if (announce && !reduce.matches) bill.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 420, delay: 160, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' });
    }
  });
  if (announce) {
    const growth = JSON.parse(cards[1].dataset.price)[cur];
    live.textContent = (yearly ? 'Yearly billing. ' : 'Monthly billing. ') + 'Growth is ' + money(yearly ? growth[1] : growth[0], cur) + ' per month' +
      (yearly ? ', ' + money(growth[1] * 12, cur) + ' billed yearly.' : '.');
  }
}

const reduce = matchMedia('(prefers-reduced-motion: reduce)');
root.addEventListener('change', (e) => { if (e.target.matches('input[type="radio"]')) render(true); });

root.addEventListener('click', (e) => {
  const cta = e.target.closest('.bkp-tiers-cta');
  if (cta) {
    const on = cta.getAttribute('aria-pressed') !== 'true';
    cards.forEach((card) => {
      const b = card.querySelector('.bkp-tiers-cta');
      const pressed = on && b === cta;
      b.setAttribute('aria-pressed', String(pressed));
      const label = b.querySelector('span');
      label.textContent = pressed ? card.dataset.name + ' selected' : label.dataset.label;
    });
    live.textContent = on ? cta.closest('.bkp-tiers-card').dataset.name + ' plan selected.' : 'Selection cleared.';
    return;
  }
  const copy = e.target.closest('.bkp-tiers-copy');
  if (copy) {
    const label = copy.querySelector('span');
    const addr = label.dataset.addr || label.textContent;
    label.dataset.addr = addr;
    const done = () => {
      copy.dataset.done = '';
      label.textContent = 'Copied — we reply within a day';
      live.textContent = 'Email address copied.';
      clearTimeout(copy._t);
      copy._t = setTimeout(() => { delete copy.dataset.done; label.textContent = addr; }, 2200);
    };
    const fallback = () => { const r = document.createRange(); r.selectNodeContents(label); const s = getSelection(); s.removeAllRanges(); s.addRange(r); };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(addr).then(done, fallback);
    else fallback();
  }
});

render(false);

