@property --bkp-usage-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.bkp-usage {
  /* re-theme: override these four */
  --bkp-usage-bg: oklch(17% 0.006 70);
  --bkp-usage-ink: oklch(94% 0.012 85);
  --bkp-usage-accent: oklch(81% 0.155 74);
  --bkp-usage-panel: oklch(20.5% 0.007 70);

  --bkp-usage-muted: color-mix(in oklch, var(--bkp-usage-ink) 56%, var(--bkp-usage-bg));
  --bkp-usage-faint: color-mix(in oklch, var(--bkp-usage-ink) 30%, var(--bkp-usage-bg));
  --bkp-usage-line: color-mix(in oklch, var(--bkp-usage-ink) 11%, transparent);
  --bkp-usage-line-2: color-mix(in oklch, var(--bkp-usage-ink) 20%, transparent);
  --bkp-usage-glow: color-mix(in oklch, var(--bkp-usage-accent) 28%, transparent);
  --bkp-usage-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkp-usage-out: cubic-bezier(.16, 1, .3, 1);
  --bkp-usage-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(70% 60% at 85% 0%, color-mix(in oklch, var(--bkp-usage-accent) 9%, transparent), transparent 70%),
    var(--bkp-usage-bg);
  color: var(--bkp-usage-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, table) { margin: 0; }
  & :where(button, input) { font: inherit; color: inherit; }
}
.bkp-usage-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-usage-in { max-width: 1180px; margin-inline: auto; padding: clamp(36px, 6cqi, 80px) clamp(16px, 4cqi, 48px); }

/* ---------- header ---------- */
.bkp-usage-head { display: grid; gap: 14px; max-width: 920px; }
.bkp-usage-brand {
  display: flex; align-items: center; gap: 9px; font-weight: 650;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkp-usage-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & span { font: 400 12px/1 var(--bkp-usage-mono); color: var(--bkp-usage-muted); }
}
.bkp-usage-title {
  font-size: clamp(30px, 4.8cqi, 56px); font-weight: 650; line-height: 1.02; letter-spacing: -.035em; text-wrap: balance;
  & span { color: var(--bkp-usage-muted); }
}
.bkp-usage-lede { max-width: 62ch; color: var(--bkp-usage-muted); font-size: clamp(15px, 1.4cqi, 16.5px); text-wrap: pretty; }
.bkp-usage-k { font: 500 11px/1.2 var(--bkp-usage-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bkp-usage-muted); }

/* ---------- layout ---------- */
.bkp-usage-calc { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; margin-top: clamp(28px, 4cqi, 44px); }
@container (width >= 900px) { .bkp-usage-calc { grid-template-columns: minmax(0, 1.6fr) minmax(320px, 1fr); } }
.bkp-usage-viz, .bkp-usage-bill {
  border-radius: 18px; background: var(--bkp-usage-panel); box-shadow: inset 0 0 0 1px var(--bkp-usage-line);
  padding: clamp(18px, 2.6cqi, 30px);
}
.bkp-usage-viz { display: grid; grid-template-rows: auto 1fr auto auto; row-gap: 18px; }

/* ---------- volume input ---------- */
.bkp-usage-vol { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "k k" "num presets" "hint hint"; align-items: center; gap: 8px 16px; }
.bkp-usage-vol .bkp-usage-k { grid-area: k; }
.bkp-usage-num {
  grid-area: num; width: 100%; min-width: 0; padding: 0 0 2px; border: 0; border-bottom: 1.5px solid var(--bkp-usage-line-2); background: none; border-radius: 0;
  font: 600 clamp(28px, 3.6cqi, 40px)/1.15 var(--bkp-usage-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums;
  caret-color: var(--bkp-usage-accent); transition: border-color .2s;
  &:hover { border-bottom-color: var(--bkp-usage-faint); }
  &:focus-visible { outline: none; border-bottom-color: var(--bkp-usage-accent); }
  &[aria-invalid="true"] { border-bottom-color: oklch(68% 0.18 25); }
}
.bkp-usage-presets {
  grid-area: presets; display: flex; gap: 6px;
  & button {
    padding: 7px 11px; border: 0; border-radius: 8px; cursor: pointer; background: color-mix(in oklch, var(--bkp-usage-ink) 6%, transparent);
    font: 500 12.5px/1 var(--bkp-usage-mono); color: var(--bkp-usage-muted); transition: background-color .2s, color .2s, transform .2s var(--bkp-usage-out);
    &:hover { color: var(--bkp-usage-ink); background: color-mix(in oklch, var(--bkp-usage-ink) 11%, transparent); }
    &:active { transform: scale(.95); }
    &:focus-visible { outline: 2px solid var(--bkp-usage-accent); outline-offset: 2px; }
    &[aria-pressed="true"] { background: var(--bkp-usage-accent); color: var(--bkp-usage-bg); }
  }
}
.bkp-usage-hint { grid-area: hint; font: 400 11.5px/1.3 var(--bkp-usage-mono); color: var(--bkp-usage-faint); }

/* ---------- chart ---------- */
.bkp-usage-chart { display: grid; grid-template-rows: 1fr auto; row-gap: 8px; min-height: clamp(180px, 24cqi, 250px); margin-top: 8px; }
.bkp-usage-axis-y { margin-top: -8px; font: 400 11px/1.4 var(--bkp-usage-mono); color: var(--bkp-usage-faint); }
.bkp-usage-plot {
  --bkp-usage-p: 0;
  position: relative; container-type: inline-size; min-height: 150px;
  background:
    radial-gradient(circle, var(--bkp-usage-line-2) 1px, transparent 1.2px) 0 100% / 16px 16px,
    linear-gradient(to right, var(--bkp-usage-line) 1px, transparent 1px) 0 0 / 25% 100%;
  border-bottom: 1px solid var(--bkp-usage-line-2);
  transition: --bkp-usage-p .7s var(--bkp-usage-spring);
  &[data-drag] { transition: none; }
}
.bkp-usage-bars { position: absolute; inset: 0; }
.bkp-usage-bar {
  position: absolute; bottom: 0; left: calc(var(--l) * 1%); width: calc(var(--w) * 1%); height: calc(var(--h) * 1%);
  clip-path: inset(0 1.5px 0 1.5px);
  background: color-mix(in oklch, var(--bkp-usage-ink) 7%, transparent);
  border-top: 1.5px solid var(--bkp-usage-line-2);
  transform-origin: bottom; transition: transform .9s var(--bkp-usage-spring) calc(var(--i) * 70ms);
  @starting-style { transform: scaleY(0); }
  &[data-free] { background: repeating-linear-gradient(-45deg, var(--bkp-usage-line-2) 0 1px, transparent 1px 6px); }
}
.bkp-usage-bars[data-layer="fill"] {
  clip-path: inset(-4px calc((1 - var(--bkp-usage-p)) * 100%) 0 0);
  & .bkp-usage-bar { background: linear-gradient(to bottom, var(--bkp-usage-accent), color-mix(in oklch, var(--bkp-usage-accent) 35%, var(--bkp-usage-panel))); border-top: 2px solid color-mix(in oklch, var(--bkp-usage-accent) 70%, white); }
  & .bkp-usage-bar[data-free] { background: repeating-linear-gradient(-45deg, var(--bkp-usage-accent) 0 1.5px, transparent 1.5px 6px); }
}
.bkp-usage-labels { position: absolute; inset: 0; pointer-events: none; }
.bkp-usage-lab {
  position: absolute; left: calc(var(--l) * 1%); bottom: calc(var(--h) * 1% + 8px); padding-left: 6px;
  font: 500 12px/1.1 var(--bkp-usage-mono); color: var(--bkp-usage-faint); white-space: nowrap; transition: color .3s;
  & small { display: block; font-size: 10px; letter-spacing: .04em; }
  &[data-last] { left: auto; right: 0; padding: 0; text-align: right; }
  &[data-on] { color: var(--bkp-usage-ink); }
  &[data-cur] { color: var(--bkp-usage-accent); }
}
.bkp-usage-cursor {
  position: absolute; top: -6px; bottom: 0; left: 0; width: 0;
  translate: calc(var(--bkp-usage-p) * 100cqi) 0;
  &::before { content: ""; position: absolute; top: 18px; bottom: 0; left: -.75px; width: 1.5px; background: var(--bkp-usage-ink); }
  &::after { content: ""; position: absolute; bottom: -4.5px; left: -4.5px; width: 9px; height: 9px; border-radius: 50%; background: var(--bkp-usage-ink); box-shadow: 0 0 0 4px var(--bkp-usage-glow); }
}
.bkp-usage-tag {
  position: absolute; top: -8px; left: 0; padding: 4px 7px; border-radius: 6px; background: var(--bkp-usage-ink); color: var(--bkp-usage-bg);
  font: 600 12px/1 var(--bkp-usage-mono); white-space: nowrap; font-variant-numeric: tabular-nums;
  translate: calc(-12% - var(--bkp-usage-p) * 76%) 0;
}
.bkp-usage-ticks { position: relative; height: 14px; font: 400 11px/1 var(--bkp-usage-mono); color: var(--bkp-usage-faint); }
.bkp-usage-tick { position: absolute; left: calc(var(--l) * 1%); translate: -50% 0; white-space: nowrap;
  &:first-child { translate: 0 0; }
  &:last-child { translate: -100% 0; }
}

/* ---------- range, aligned to the plot ---------- */
.bkp-usage-track { margin-inline: -11px; }
.bkp-usage-range {
  display: block; width: 100%; height: 30px; margin: 0; background: none; cursor: pointer; -webkit-appearance: none; appearance: none;
  accent-color: var(--bkp-usage-accent);
  &::-webkit-slider-runnable-track { height: 4px; border-radius: 4px; background: linear-gradient(to right, var(--bkp-usage-accent) calc(11px + var(--fill, 0) * (100% - 22px)), var(--bkp-usage-line-2) 0); }
  &::-webkit-slider-thumb { -webkit-appearance: none; width: 22px; height: 22px; margin-top: -9px; border-radius: 50%; background: var(--bkp-usage-ink); border: 5px solid var(--bkp-usage-accent); box-shadow: 0 0 0 6px var(--bkp-usage-glow); transition: transform .25s var(--bkp-usage-out); }
  &:active::-webkit-slider-thumb { transform: scale(1.12); }
  &::-moz-range-track { height: 4px; border-radius: 4px; background: var(--bkp-usage-line-2); }
  &::-moz-range-progress { height: 4px; border-radius: 4px; background: var(--bkp-usage-accent); }
  &::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: var(--bkp-usage-ink); border: 5px solid var(--bkp-usage-accent); box-shadow: 0 0 0 6px var(--bkp-usage-glow); }
  &:focus-visible { outline: 2px dashed var(--bkp-usage-accent); outline-offset: 2px; border-radius: 8px; }
}

/* ---------- bill ---------- */
.bkp-usage-bill { display: grid; align-content: start; gap: 6px; }
.bkp-usage-total {
  display: flex; align-items: flex-start; gap: 4px; margin-top: 6px;
  font: 650 clamp(46px, 5.6cqi, 66px)/1 system-ui, -apple-system, sans-serif; letter-spacing: -.045em; font-variant-numeric: tabular-nums;
}
.bkp-usage-cur { font-size: .5em; line-height: 1.3; color: var(--bkp-usage-accent); }
.bkp-usage-eff { font: 400 12.5px/1.5 var(--bkp-usage-mono); color: var(--bkp-usage-muted); text-wrap: pretty;
  & b { font-weight: 600; color: var(--bkp-usage-accent); }
}
.bkp-usage-lines {
  width: 100%; margin-top: 16px; border-collapse: collapse; font: 400 12.5px/1.3 var(--bkp-usage-mono); font-variant-numeric: tabular-nums;
  & th, & td { padding: 9px 0; text-align: right; border-bottom: 1px solid var(--bkp-usage-line); font-weight: 400; }
  & :is(th, td):first-child { text-align: left; }
  & thead th { padding-top: 0; font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--bkp-usage-faint); }
  & tbody tr { transition: opacity .3s, background-color .3s; }
  & tbody tr[data-state="none"] { opacity: .38; }
  & tbody tr[data-state="part"] { background: linear-gradient(to right, var(--bkp-usage-glow), transparent 70%); }
  & .bkp-usage-band { display: flex; align-items: center; gap: 9px; }
  & tbody th i { flex: none; width: 8px; height: 8px; border-radius: 2px; background: var(--bkp-usage-accent); }
  & tbody tr[data-free] th i { background: repeating-linear-gradient(-45deg, var(--bkp-usage-accent) 0 1.5px, transparent 1.5px 3.5px); box-shadow: inset 0 0 0 1px var(--bkp-usage-accent); }
  & tbody th small { display: block; color: var(--bkp-usage-muted); font-size: 11px; }
  & tbody tr[data-state="part"] .bkp-usage-band { padding-left: 6px; }
  & tfoot :is(th, td) { border-bottom: 0; padding-top: 12px; font-weight: 600; color: var(--bkp-usage-ink); }
}
.bkp-usage-foot { margin-top: 12px; padding-top: 14px; border-top: 1px dashed var(--bkp-usage-line-2); font-size: 13px; color: var(--bkp-usage-muted); text-wrap: pretty;
  & b { color: var(--bkp-usage-ink); font-weight: 600; }
}

@container (width < 560px) {
  .bkp-usage-vol { grid-template-areas: "k" "num" "presets" "hint"; grid-template-columns: minmax(0, 1fr); }
  .bkp-usage-presets button { flex: 1; }
  .bkp-usage-hint { display: none; }
  .bkp-usage-lab small { display: none; }
  .bkp-usage-tick:last-child { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-usage-plot, .bkp-usage-bar { transition: none; }
  .bkp-usage-lines tbody tr, .bkp-usage-lab { transition: none; }
  .bkp-usage-range::-webkit-slider-thumb { transition: none; }
}

