/* One source of truth: graduated bands, [from, to, $ per 1,000]. */
const BANDS = [[0, 3000, 0], [3000, 50000, 0.8], [50000, 500000, 0.55], [500000, 5000000, 0.35], [5000000, Infinity, 0.2]];
const MIN = 1000, MAX = 10000000, FLAT = 0.8;
const pos = (x) => (Math.log10(x) - 3) / 4;                 /* 1k..10M on a log axis -> 0..1 */
const fromPos = (p) => 10 ** (3 + 4 * p);
const nice = (x) => { const m = 10 ** (Math.floor(Math.log10(x)) - 1); return Math.min(MAX, Math.max(MIN, Math.round(x / m) * m)); };
const int = new Intl.NumberFormat('en');
const usd = new Intl.NumberFormat('en', { style: 'currency', currency: 'USD', minimumFractionDigits: 2 });
const usd3 = new Intl.NumberFormat('en', { style: 'currency', currency: 'USD', minimumFractionDigits: 3, maximumFractionDigits: 3 });
const compact = new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 1 });
const short = (n) => compact.format(n).replace('K', 'k');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

const plot = root.querySelector('.bkp-usage-plot');
const range = root.querySelector('.bkp-usage-range');
const num = root.querySelector('.bkp-usage-num');
const tag = root.querySelector('.bkp-usage-tag');
const tbody = root.querySelector('.bkp-usage-lines tbody');
const totalEl = root.querySelector('[data-total]');
const presets = [...root.querySelectorAll('.bkp-usage-presets button')];
const live = root.querySelector('[data-live]');
let liveT = 0;

/* ---- draw bars, labels, ticks and receipt rows from BANDS ---- */
const top = Math.max(...BANDS.map((b) => b[2]));
const bandGeo = BANDS.map(([lo, hi, rate], i) => {
  const l = pos(Math.max(lo, MIN)) * 100, r = pos(Math.min(hi, MAX)) * 100;
  return { l, w: r - l, h: rate ? 12 + (rate / top) * 62 : 7, lo, hi, rate, i };
});
const barHTML = bandGeo.map((g) => '<i class="bkp-usage-bar"' + (g.rate ? '' : ' data-free') + ' style="--i:' + g.i + ';--l:' + g.l + ';--w:' + g.w + ';--h:' + g.h + '"></i>').join('');
root.querySelectorAll('.bkp-usage-bars').forEach((el) => { el.innerHTML = barHTML; });
root.querySelector('.bkp-usage-labels').innerHTML = bandGeo.map((g, i) =>
  '<span class="bkp-usage-lab"' + (i === BANDS.length - 1 ? ' data-last' : '') + ' style="--l:' + g.l + ';--h:' + g.h + '">' +
  (g.rate ? '$' + g.rate.toFixed(2) + '<small>/ 1k</small>' : 'FREE<small>first 3k</small>') + '</span>').join('');
const edges = [MIN, ...BANDS.slice(1).map((b) => b[0]), MAX];
root.querySelector('.bkp-usage-ticks').innerHTML = edges.map((x) => '<span class="bkp-usage-tick" style="--l:' + pos(x) * 100 + '">' + short(x) + '</span>').join('');
const rangeLabel = (lo, hi) => short(lo) + '–' + (hi === Infinity ? '∞' : short(hi));
tbody.innerHTML = BANDS.map(([lo, hi, rate]) =>
  '<tr' + (rate ? '' : ' data-free') + '><th scope="row"><span class="bkp-usage-band"><i></i><span>' + (rate ? '$' + rate.toFixed(2) + ' / 1k' : 'Free tier') +
  '<small>' + rangeLabel(lo, hi) + '</small></span></span></th><td data-n></td><td data-c></td></tr>').join('');
const rows = [...tbody.rows];
const labs = [...root.querySelectorAll('.bkp-usage-lab')];

/* ---- pricing ---- */
function bill(x) {
  const parts = BANDS.map(([lo, hi, rate]) => { const n = Math.max(0, Math.min(x, hi) - lo); return { n, cost: (n * rate) / 1000 }; });
  const total = parts.reduce((s, p) => s + p.cost, 0);
  return { parts, total: Math.round(total * 100) / 100 };
}

let shown = 0, raf = 0;
function tweenTotal(to, instant) {
  cancelAnimationFrame(raf);
  if (instant || reduce.matches) { shown = to; totalEl.textContent = usd.format(to).slice(1); return; }
  const from = shown, t0 = performance.now(), dur = 380;
  const step = (now) => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / dur), e = 1 - (1 - k) ** 3;
    shown = from + (to - from) * e;
    totalEl.textContent = usd.format(shown).slice(1);
    if (k < 1) raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
}

let x = 1200000;
function set(nx, opts = {}) {
  x = Math.min(MAX, Math.max(MIN, nx));
  const p = pos(x);
  const { parts, total } = bill(x);
  plot.style.setProperty('--bkp-usage-p', p);
  range.style.setProperty('--fill', p);
  if (!opts.fromRange) range.value = Math.round(p * 1000);
  range.setAttribute('aria-valuetext', int.format(x) + ' emails per month, ' + usd.format(total));
  if (!opts.typing) num.value = int.format(x);
  num.removeAttribute('aria-invalid');
  tag.textContent = short(x);
  const cur = BANDS.findIndex(([lo, hi]) => x > lo && x <= hi);
  parts.forEach((pt, i) => {
    const r = rows[i];
    r.dataset.state = pt.n === 0 ? 'none' : i === cur ? 'part' : 'full';
    r.querySelector('[data-n]').textContent = int.format(pt.n);
    r.querySelector('[data-c]').textContent = usd.format(pt.cost);
    labs[i].toggleAttribute('data-on', pt.n > 0);
    labs[i].toggleAttribute('data-cur', i === cur);
  });
  root.querySelector('[data-sum-n]').textContent = int.format(x);
  root.querySelector('[data-sum]').textContent = usd.format(total);
  root.querySelector('[data-eff]').textContent = usd3.format((total / x) * 1000);
  const flat = (Math.max(0, x - 3000) * FLAT) / 1000;
  root.querySelector('[data-save]').innerHTML = flat - total > 0.005
    ? '<b>' + usd.format(flat - total) + ' less</b> than a flat $' + FLAT.toFixed(2) + ' rate'
    : 'volume discounts begin after ' + int.format(BANDS[2][0]);
  presets.forEach((b) => b.setAttribute('aria-pressed', String(+b.dataset.x === x)));
  tweenTotal(total, opts.instant);
  clearTimeout(liveT);
  if (!opts.instant) liveT = setTimeout(() => { live.textContent = int.format(x) + ' emails a month: ' + usd.format(total) + '.'; }, 500);
}

/* ---- controls ---- */
range.addEventListener('pointerdown', () => plot.setAttribute('data-drag', ''));
const endDrag = () => plot.removeAttribute('data-drag');
range.addEventListener('pointerup', endDrag);
range.addEventListener('pointercancel', endDrag);
range.addEventListener('input', () => set(nice(fromPos(range.value / 1000)), { fromRange: true }));
range.addEventListener('keydown', () => plot.removeAttribute('data-drag'));
presets.forEach((b) => b.addEventListener('click', () => { endDrag(); set(+b.dataset.x); }));

function parse(s) {
  const m = String(s).trim().toLowerCase().replace(/[,\s_]/g, '').match(/^(\d*\.?\d+)([km]?)$/);
  if (!m) return NaN;
  return Math.round(parseFloat(m[1]) * (m[2] === 'm' ? 1e6 : m[2] === 'k' ? 1e3 : 1));
}
function commit() {
  const v = parse(num.value);
  if (Number.isNaN(v)) { num.setAttribute('aria-invalid', 'true'); return; }
  endDrag();
  set(v);
}
num.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); commit(); }
  else if (e.key === 'Escape') { num.value = int.format(x); num.removeAttribute('aria-invalid'); }
  else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    e.preventDefault();
    const p = pos(x) + (e.key === 'ArrowUp' ? 1 : -1) * (e.shiftKey ? 0.1 : 0.025);
    endDrag();
    set(nice(fromPos(Math.min(1, Math.max(0, p)))));
  }
});
num.addEventListener('blur', commit);
num.addEventListener('input', () => {
  const v = parse(num.value);
  if (!Number.isNaN(v) && v >= MIN && v <= MAX) set(v, { typing: true });
});

set(x, { instant: true });

