@property --bkp-matrix-s { syntax: "<number>"; inherits: true; initial-value: 0; }

.bkp-matrix {
  /* re-theme: override these four */
  --bkp-matrix-paper: oklch(96.6% 0.017 85);
  --bkp-matrix-ink: oklch(23% 0.025 45);
  --bkp-matrix-accent: oklch(47% 0.15 27);
  --bkp-matrix-sheet: oklch(98.6% 0.009 85);

  --bkp-matrix-muted: color-mix(in oklch, var(--bkp-matrix-ink) 60%, var(--bkp-matrix-paper));
  --bkp-matrix-rule: color-mix(in oklch, var(--bkp-matrix-ink) 13%, transparent);
  --bkp-matrix-rule-2: color-mix(in oklch, var(--bkp-matrix-ink) 32%, transparent);
  --bkp-matrix-tint: color-mix(in oklch, var(--bkp-matrix-accent) 7%, var(--bkp-matrix-sheet));
  --bkp-matrix-hover: color-mix(in oklch, var(--bkp-matrix-ink) 3.5%, var(--bkp-matrix-sheet));
  --bkp-matrix-serif: ui-serif, "New York", "Iowan Old Style", Charter, "Palatino Linotype", Georgia, serif;
  --bkp-matrix-out: cubic-bezier(.2, .9, .25, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkp-matrix-paper);
  color: var(--bkp-matrix-ink);
  font: 400 14.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, fieldset, legend) { margin: 0; padding: 0; border: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & sup { font-size: .68em; line-height: 0; margin-left: 1px; color: var(--bkp-matrix-accent); font-feature-settings: "sups"; }
}
.bkp-matrix-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-matrix-in { max-width: 1180px; margin-inline: auto; padding: clamp(36px, 6cqi, 80px) clamp(16px, 4cqi, 48px); }

/* ---------- masthead ---------- */
.bkp-matrix-head {
  display: grid; gap: 14px; padding-bottom: clamp(22px, 3cqi, 34px); border-bottom: 3px double var(--bkp-matrix-rule-2);
}
.bkp-matrix-kicker {
  display: flex; align-items: center; gap: 8px; font-size: 12px; letter-spacing: .14em; text-transform: uppercase;
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--bkp-matrix-accent); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
  & b { font-weight: 700; }
  & span { color: var(--bkp-matrix-muted); }
  & span::before { content: "/"; margin-right: 8px; color: var(--bkp-matrix-rule-2); }
}
.bkp-matrix-title {
  max-width: 22ch; font: 400 clamp(32px, 5cqi, 60px)/1.02 var(--bkp-matrix-serif); letter-spacing: -.022em; text-wrap: balance;
  & em { font-style: italic; color: var(--bkp-matrix-accent); }
}
.bkp-matrix-lede { max-width: 58ch; font: 400 clamp(15px, 1.45cqi, 17px)/1.55 var(--bkp-matrix-serif); color: var(--bkp-matrix-muted); text-wrap: pretty; }
@container (width >= 900px) {
  .bkp-matrix-head { grid-template-columns: minmax(0, 1.45fr) minmax(0, 1fr); grid-template-areas: "kick kick" "title lede"; align-items: end; column-gap: 5cqi; }
  .bkp-matrix-kicker { grid-area: kick; }
  .bkp-matrix-title { grid-area: title; }
  .bkp-matrix-lede { grid-area: lede; }
}

/* ---------- plan picker (narrow only; the same radios drive the column highlight when wide) ---------- */
.bkp-matrix-pick {
  display: none; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px; margin-top: 20px; padding: 4px;
  border-radius: 12px; background: var(--bkp-matrix-sheet); box-shadow: inset 0 0 0 1px var(--bkp-matrix-rule);
  & legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  & label { position: relative; display: grid; justify-items: center; gap: 1px; padding: 8px 2px; border-radius: 9px; cursor: pointer; transition: background-color .25s, color .25s; }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & span { font-weight: 650; font-size: 13.5px; }
  & small { font: 400 12px/1 var(--bkp-matrix-serif); color: var(--bkp-matrix-muted); font-variant-numeric: tabular-nums; }
  & label:has(input:checked) { background: var(--bkp-matrix-ink); color: var(--bkp-matrix-paper); & small { color: inherit; opacity: .7; } }
  & label:has(input:focus-visible) { outline: 2px solid var(--bkp-matrix-accent); outline-offset: 2px; }
}

/* ---------- scroller + table ---------- */
.bkp-matrix-scroll {
  position: relative; margin-top: clamp(18px, 2.4cqi, 26px); max-height: 560px; overflow: auto; overscroll-behavior: contain;
  border-radius: 4px; background: var(--bkp-matrix-sheet); box-shadow: 0 0 0 1px var(--bkp-matrix-rule), 0 24px 50px -36px color-mix(in oklch, var(--bkp-matrix-ink) 40%, transparent);
  scrollbar-width: thin; scrollbar-color: var(--bkp-matrix-rule-2) transparent;
  &:focus-visible { outline: 2px solid var(--bkp-matrix-accent); outline-offset: 3px; }
}
.bkp-matrix-table {
  --bkp-matrix-hh: 170px;
  width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed;
  & col, & th, & td { text-align: left; }
  & :is(th, td) { padding: 11px 14px; border-bottom: 1px solid var(--bkp-matrix-rule); vertical-align: middle; transition: background-color .2s; }
  & tbody th { width: 30%; font-weight: 500; }
  & tbody td { font-variant-numeric: tabular-nums; font-size: 14px; }
  & tbody tr:hover > * { background: var(--bkp-matrix-hover); }
}
@supports (animation-timeline: scroll()) {
  .bkp-matrix-table { animation: bkp-matrix-condense linear both; animation-timeline: scroll(nearest block); animation-range: 0 140px; }
}
@keyframes bkp-matrix-condense { from { --bkp-matrix-s: 0; } to { --bkp-matrix-s: 1; } }

/* sticky header that condenses as the table scrolls */
.bkp-matrix-table thead :is(th, td) {
  position: sticky; top: 0; z-index: 3; vertical-align: bottom; background: var(--bkp-matrix-sheet);
  padding-top: calc(34px - var(--bkp-matrix-s) * 24px); padding-bottom: calc(16px - var(--bkp-matrix-s) * 6px);
  border-bottom: 1.5px solid var(--bkp-matrix-ink);
}
.bkp-matrix-table thead :is(th, td)::after {
  content: ""; position: absolute; left: 0; right: 0; top: calc(100% + 1.5px); height: 16px; pointer-events: none;
  background: linear-gradient(color-mix(in oklch, var(--bkp-matrix-ink) calc(var(--bkp-matrix-s) * 12%), transparent), transparent);
}
.bkp-matrix-corner { width: 30%;
  & span { display: block; }
}
.bkp-matrix-corner-t { font: italic 400 calc(22px - var(--bkp-matrix-s) * 4px)/1.1 var(--bkp-matrix-serif); }
.bkp-matrix-corner-s { margin-top: 4px; font-size: 12px; color: var(--bkp-matrix-muted); opacity: calc(1 - var(--bkp-matrix-s)); }
.bkp-matrix-plan { position: relative; display: grid; justify-items: start; }
.bkp-matrix-flag {
  position: absolute; bottom: 100%; left: 0; margin-bottom: 4px; padding: 3px 7px; border-radius: 3px; background: var(--bkp-matrix-accent); color: var(--bkp-matrix-sheet);
  font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; white-space: nowrap;
  opacity: calc(1 - var(--bkp-matrix-s) * 2); translate: 0 calc(var(--bkp-matrix-s) * 6px);
}
.bkp-matrix-name { font-size: 11.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.bkp-matrix-price {
  display: flex; align-items: flex-start; margin-top: calc(6px - var(--bkp-matrix-s) * 4px);
  font: 400 calc(clamp(26px, 3.1cqi, 38px) * (1 - var(--bkp-matrix-s) * .38))/1 var(--bkp-matrix-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums lining-nums;
}
.bkp-matrix-cur { font-size: .5em; margin: .12em .06em 0 0; }
.bkp-matrix-per { align-self: flex-end; margin-left: 3px; font: 400 12px/1.6 system-ui, sans-serif; color: var(--bkp-matrix-muted); }
.bkp-matrix-desc {
  overflow: hidden; height: calc((1 - var(--bkp-matrix-s)) * 2.7em); margin-top: calc((1 - var(--bkp-matrix-s)) * 6px);
  font: italic 400 13.5px/1.35 var(--bkp-matrix-serif); color: var(--bkp-matrix-muted); text-wrap: balance;
  opacity: calc(1 - var(--bkp-matrix-s) * 1.8);
}
.bkp-matrix-cta {
  margin-top: calc(14px - var(--bkp-matrix-s) * 8px); padding: calc(8px - var(--bkp-matrix-s) * 3px) 12px; border: 1px solid var(--bkp-matrix-ink); border-radius: 3px;
  background: transparent; cursor: pointer; font-size: 12.5px; font-weight: 650; white-space: nowrap;
  transition: background-color .2s, color .2s, transform .2s var(--bkp-matrix-out);
  &:hover { background: var(--bkp-matrix-ink); color: var(--bkp-matrix-sheet); }
  &:active { transform: scale(.97); }
  &:focus-visible { outline: 2px solid var(--bkp-matrix-accent); outline-offset: 2px; }
  &[aria-pressed="true"] { background: var(--bkp-matrix-accent); border-color: var(--bkp-matrix-accent); color: var(--bkp-matrix-sheet); }
}

/* section labels stick beneath the header */
.bkp-matrix-group :is(th, td) {
  position: sticky; top: var(--bkp-matrix-hh); z-index: 2; padding-top: 18px; padding-bottom: 7px;
  background: var(--bkp-matrix-sheet); border-bottom: 1px solid var(--bkp-matrix-rule-2);
  & span { font: italic 400 17px/1 var(--bkp-matrix-serif); color: var(--bkp-matrix-accent); white-space: nowrap; }
}
.bkp-matrix-table tbody tr.bkp-matrix-group:hover > * { background: var(--bkp-matrix-sheet); }
.bkp-matrix-yes svg { width: 18px; height: 18px; fill: none; stroke: var(--bkp-matrix-ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; vertical-align: middle; }
.bkp-matrix-no { display: inline-block; width: 12px; height: 1.5px; vertical-align: middle; background: var(--bkp-matrix-rule-2); }

/* the chosen column, from the radios (CTA or narrow tabs) */
.bkp-matrix:has(.bkp-matrix-pick input[value="1"]:checked) .bkp-matrix-table :is(th, td):nth-child(2),
.bkp-matrix:has(.bkp-matrix-pick input[value="2"]:checked) .bkp-matrix-table :is(th, td):nth-child(3),
.bkp-matrix:has(.bkp-matrix-pick input[value="3"]:checked) .bkp-matrix-table :is(th, td):nth-child(4),
.bkp-matrix:has(.bkp-matrix-pick input[value="4"]:checked) .bkp-matrix-table :is(th, td):nth-child(5) {
  background: var(--bkp-matrix-tint); box-shadow: inset 1px 0 0 color-mix(in oklch, var(--bkp-matrix-accent) 22%, transparent), inset -1px 0 0 color-mix(in oklch, var(--bkp-matrix-accent) 22%, transparent);
}
/* hovering any cell lights its whole column */
.bkp-matrix-table:has(:is(td, th):nth-child(2):hover) :is(td, th):nth-child(2),
.bkp-matrix-table:has(:is(td, th):nth-child(3):hover) :is(td, th):nth-child(3),
.bkp-matrix-table:has(:is(td, th):nth-child(4):hover) :is(td, th):nth-child(4),
.bkp-matrix-table:has(:is(td, th):nth-child(5):hover) :is(td, th):nth-child(5) { color: var(--bkp-matrix-accent); }
.bkp-matrix-table:has(:is(td, th):nth-child(n+2):hover) :is(td, th):nth-child(n+2) svg { transition: stroke .2s; }
.bkp-matrix-table:has(:is(td, th):nth-child(2):hover) td:nth-child(2) svg,
.bkp-matrix-table:has(:is(td, th):nth-child(3):hover) td:nth-child(3) svg,
.bkp-matrix-table:has(:is(td, th):nth-child(4):hover) td:nth-child(4) svg,
.bkp-matrix-table:has(:is(td, th):nth-child(5):hover) td:nth-child(5) svg { stroke: var(--bkp-matrix-accent); }
.bkp-matrix-table thead th:nth-child(n+2)::before {
  content: ""; position: absolute; inset: 0 0 auto; height: 3px; background: var(--bkp-matrix-accent); transform: scaleX(0); transform-origin: left; transition: transform .45s var(--bkp-matrix-out);
}
.bkp-matrix:has(.bkp-matrix-pick input[value="1"]:checked) thead th:nth-child(2)::before,
.bkp-matrix:has(.bkp-matrix-pick input[value="2"]:checked) thead th:nth-child(3)::before,
.bkp-matrix:has(.bkp-matrix-pick input[value="3"]:checked) thead th:nth-child(4)::before,
.bkp-matrix:has(.bkp-matrix-pick input[value="4"]:checked) thead th:nth-child(5)::before { transform: scaleX(1); }

.bkp-matrix-notes {
  display: flex; flex-wrap: wrap; gap: 4px 22px; margin-top: 16px; font: 400 12.5px/1.5 var(--bkp-matrix-serif); color: var(--bkp-matrix-muted);
  & b { font-weight: 600; color: var(--bkp-matrix-ink); }
}

/* ---------- narrow: one plan at a time ---------- */
@container (width < 640px) {
  .bkp-matrix-pick { display: grid; }
  .bkp-matrix-scroll { max-height: 520px; }
  .bkp-matrix-table :is(th, td):nth-child(n+2) { display: none; }
  .bkp-matrix-table :is(tbody th, .bkp-matrix-corner) { width: 56%; }
  .bkp-matrix-table :is(th, td) { padding-inline: 12px; }
  .bkp-matrix:has(.bkp-matrix-pick input[value="1"]:checked) .bkp-matrix-table :is(th, td):nth-child(2),
  .bkp-matrix:has(.bkp-matrix-pick input[value="2"]:checked) .bkp-matrix-table :is(th, td):nth-child(3),
  .bkp-matrix:has(.bkp-matrix-pick input[value="3"]:checked) .bkp-matrix-table :is(th, td):nth-child(4),
  .bkp-matrix:has(.bkp-matrix-pick input[value="4"]:checked) .bkp-matrix-table :is(th, td):nth-child(5) { display: table-cell; box-shadow: none; }
  .bkp-matrix-flag { display: none; }
  .bkp-matrix-corner-t { font-size: calc(19px - var(--bkp-matrix-s) * 3px); }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-matrix-table { animation: none; }
  .bkp-matrix-table thead th:nth-child(n+2)::before, .bkp-matrix-cta, .bkp-matrix-table :is(th, td) { transition: none; }
}

