const uid = Math.random().toString(36).slice(2, 8);
const radios = [...root.querySelectorAll('.bkp-matrix-pick input')];
radios.forEach((r) => { r.name = r.name + '-' + uid; });
const ctas = [...root.querySelectorAll('.bkp-matrix-cta')];
const labels = ctas.map((b) => b.dataset.col === '3' ? 'Choose Imprint' : b.textContent);
const table = root.querySelector('.bkp-matrix-table');
const thead = table.tHead;
const scroller = root.querySelector('.bkp-matrix-scroll');

function sync() {
  const v = radios.find((r) => r.checked).value;
  ctas.forEach((b, i) => {
    const on = b.dataset.col === v;
    b.setAttribute('aria-pressed', String(on));
    b.textContent = on ? 'Selected' : labels[i];
  });
}
root.addEventListener('change', (e) => { if (radios.includes(e.target)) sync(); });
ctas.forEach((b) => b.addEventListener('click', () => {
  const r = radios.find((x) => x.value === b.dataset.col);
  r.checked = true;
  sync();
}));

/* Section labels stick directly beneath the header, whose height changes as it condenses. */
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  table.style.setProperty('--bkp-matrix-hh', thead.offsetHeight + 'px');
});
ro.observe(thead);

/* Without scroll-driven animations, drive the same custom property from the scroller. */
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
if (!CSS.supports('animation-timeline: scroll()') && !reduce.matches) {
  let queued = false;
  scroller.addEventListener('scroll', () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      if (!root.isConnected) return;
      queued = false;
      table.style.setProperty('--bkp-matrix-s', Math.min(1, scroller.scrollTop / 140).toFixed(3));
    });
  }, { passive: true });
}

/* Arrow keys scroll the table a row at a time when the region has focus. */
scroller.addEventListener('keydown', (e) => {
  if (e.target !== scroller) return;
  const step = { ArrowDown: 44, ArrowUp: -44, PageDown: scroller.clientHeight * 0.8, PageUp: -scroller.clientHeight * 0.8 }[e.key];
  if (step === undefined) return;
  e.preventDefault();
  scroller.scrollBy({ top: step, behavior: reduce.matches ? 'auto' : 'smooth' });
});
sync();

