.bkp-seats {
  /* re-theme: override paper, ink and the three band colours */
  --bkp-seats-paper: oklch(95.6% 0.05 93);
  --bkp-seats-ink: oklch(27% 0.045 35);
  --bkp-seats-b0: oklch(67% 0.18 33);
  --bkp-seats-b1: oklch(71% 0.115 178);
  --bkp-seats-b2: oklch(73% 0.14 352);

  --bkp-seats-card: color-mix(in oklch, var(--bkp-seats-paper) 55%, white);
  --bkp-seats-muted: color-mix(in oklch, var(--bkp-seats-ink) 64%, var(--bkp-seats-paper));
  --bkp-seats-line: color-mix(in oklch, var(--bkp-seats-ink) 14%, transparent);
  --bkp-seats-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  --bkp-seats-pop: linear(0, .045, .171 3.4%, .652 11.3%, .874 15.5%, 1.008 19.7%, 1.104 24.4%, 1.139 27.5%, 1.149 30.9%, 1.131 35.6%, 1.033 46.4%, .996 52.6%, .98 58.9%, .983 68.4%, 1.003 85.2%, 1);
  --bkp-seats-out: cubic-bezier(.2, .9, .3, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(40% 50% at 0% 0%, color-mix(in oklch, var(--bkp-seats-b2) 18%, transparent), transparent 70%),
    radial-gradient(45% 55% at 100% 100%, color-mix(in oklch, var(--bkp-seats-b1) 20%, transparent), transparent 70%),
    var(--bkp-seats-paper);
  color: var(--bkp-seats-ink);
  font: 500 15px/1.5 var(--bkp-seats-round);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button, input, output) { font: inherit; color: inherit; }
}
.bkp-seats-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-seats-in { max-width: 1180px; margin-inline: auto; padding: clamp(36px, 6cqi, 80px) clamp(16px, 4cqi, 48px); }

/* ---------- header ---------- */
.bkp-seats-head { display: grid; gap: 12px; max-width: 860px; }
.bkp-seats-brand {
  display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 17px; letter-spacing: -.01em;
  & svg { width: 26px; height: 26px; fill: var(--bkp-seats-b0); stroke: var(--bkp-seats-ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & svg path:last-child { fill: none; }
}
.bkp-seats-title {
  font-size: clamp(32px, 5.2cqi, 60px); font-weight: 800; line-height: 1; letter-spacing: -.035em; text-wrap: balance;
  & span { color: color-mix(in oklch, var(--bkp-seats-b0) 75%, var(--bkp-seats-ink)); }
}
.bkp-seats-lede { max-width: 58ch; font-weight: 450; font-size: clamp(15px, 1.45cqi, 17px); color: var(--bkp-seats-muted); text-wrap: pretty; }

/* ---------- board ---------- */
.bkp-seats-board {
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "sum" "stage" "bill"; gap: 14px;
  margin-top: clamp(26px, 4cqi, 44px);
}
@container (width >= 820px) {
  .bkp-seats-board { grid-template-columns: minmax(0, 1.55fr) minmax(300px, 1fr); grid-template-areas: "stage sum" "stage bill"; grid-template-rows: auto 1fr; column-gap: 18px; }
}
.bkp-seats-sum, .bkp-seats-stage, .bkp-seats-bill { border-radius: 24px; background: var(--bkp-seats-card); box-shadow: 0 0 0 2px var(--bkp-seats-ink), 4px 5px 0 2px var(--bkp-seats-ink); }
.bkp-seats-sum { grid-area: sum; position: relative; padding: 20px 22px; }
.bkp-seats-stage { grid-area: stage; display: grid; align-content: space-between; gap: 22px; padding: clamp(18px, 2.4cqi, 28px); }
.bkp-seats-bill { grid-area: bill; display: grid; align-content: start; gap: 14px; padding: 20px 22px; }

.bkp-seats-k { font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--bkp-seats-muted); }
.bkp-seats-count { display: flex; align-items: baseline; gap: 8px; margin-top: 2px; font-size: 18px; font-weight: 700; }
.bkp-seats-n { font-size: 44px; font-weight: 850; line-height: 1; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.bkp-seats-plan { font-weight: 600; color: var(--bkp-seats-muted); }
.bkp-seats-plan-slot { display: inline-grid; vertical-align: bottom; overflow: clip; padding-inline: 2px;
  & b { grid-area: 1 / 1; color: var(--bkp-seats-ink); font-weight: 800; }
}
.bkp-seats-total {
  display: flex; align-items: flex-start; gap: 2px; margin-top: 14px; padding-top: 14px; border-top: 2px dashed var(--bkp-seats-line);
  & b { font-size: clamp(48px, 5.4cqi, 64px); font-weight: 850; line-height: .95; letter-spacing: -.045em; font-variant-numeric: tabular-nums; }
  & small { align-self: flex-end; margin: 0 0 6px 6px; font-size: 15px; font-weight: 700; color: var(--bkp-seats-muted); }
}
.bkp-seats-cur { font-size: 26px; font-weight: 800; line-height: 1.3; }
.bkp-seats-avg { margin-top: 4px; font-size: 14px; font-weight: 600; color: var(--bkp-seats-muted); font-variant-numeric: tabular-nums; }

/* ---------- the room of seats ---------- */
.bkp-seats-room { --cols: 15; display: grid; grid-template-columns: repeat(var(--cols), minmax(0, 40px)); justify-content: center; gap: clamp(3px, .85cqi, 9px); }
.bkp-seats-s {
  --c: var(--bkp-seats-b0);
  position: relative; aspect-ratio: 1; border-radius: 50%;
  background: transparent; box-shadow: inset 0 0 0 1.5px var(--bkp-seats-line);
  transform: scale(.5); transition: transform .3s var(--bkp-seats-out), background-color .2s, box-shadow .2s;
  &[data-b="1"] { --c: var(--bkp-seats-b1); }
  &[data-b="2"] { --c: var(--bkp-seats-b2); }
  &::before, &::after { content: ""; position: absolute; opacity: 0; transition: opacity .15s; }
  /* eyes */
  &::before { left: 26%; right: 26%; top: 32%; height: 18%;
    background: radial-gradient(circle closest-side, var(--bkp-seats-ink) 70%, transparent 76%) left / 30% 100% no-repeat,
                radial-gradient(circle closest-side, var(--bkp-seats-ink) 70%, transparent 76%) right / 30% 100% no-repeat; }
  /* smile */
  &::after { left: 33%; right: 33%; top: 50%; height: 18%; border: 0 solid var(--bkp-seats-ink); border-bottom-width: max(1.5px, .09em); border-radius: 0 0 50% 50% / 0 0 100% 100%; }
  &[data-on] {
    background: color-mix(in oklch, var(--c) calc(74% + var(--r) * 26%), white); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--c) 60%, var(--bkp-seats-ink));
    transform: none; transition: transform .7s var(--bkp-seats-pop) calc(var(--d, 0) * 1ms), background-color .2s calc(var(--d, 0) * 1ms), box-shadow .2s calc(var(--d, 0) * 1ms);
    &::before, &::after { opacity: 1; transition-delay: calc(var(--d, 0) * 1ms + 120ms); }
    &::before { animation: bkp-seats-blink 7s calc(var(--r) * -7s) infinite; }
    @starting-style { transform: scale(.5); background-color: transparent; }
  }
  &:not([data-on]) { transition-delay: calc(var(--d, 0) * 1ms); }
}
.bkp-seats-room { font-size: clamp(16px, 2.4cqi, 26px); }
@keyframes bkp-seats-blink { 0%, 95%, 100% { transform: scaleY(1); } 97% { transform: scaleY(.1); } }
@keyframes bkp-seats-wave { 0%, 100% { translate: 0 0; } 40% { translate: 0 -38%; } 70% { translate: 0 6%; } }
.bkp-seats-room[data-wave] .bkp-seats-s[data-on] { animation: bkp-seats-wave .6s var(--bkp-seats-out) calc(var(--w) * 1ms) both; }
.bkp-seats.is-off .bkp-seats-s::before { animation-play-state: paused; }

/* ---------- slider ---------- */
.bkp-seats-ctl { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: start; gap: 12px; }
.bkp-seats-step {
  display: grid; place-items: center; width: 44px; height: 44px; border: 0; border-radius: 50%; cursor: pointer;
  background: var(--bkp-seats-paper); box-shadow: 0 0 0 2px var(--bkp-seats-ink), 0 3px 0 2px var(--bkp-seats-ink);
  transition: transform .15s var(--bkp-seats-out), box-shadow .15s var(--bkp-seats-out), background-color .2s;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; }
  &:hover { background: color-mix(in oklch, var(--bkp-seats-b0) 25%, var(--bkp-seats-paper)); }
  &:active { transform: translateY(3px); box-shadow: 0 0 0 2px var(--bkp-seats-ink), 0 0 0 2px var(--bkp-seats-ink); }
  &:focus-visible { outline: 3px solid var(--bkp-seats-b0); outline-offset: 3px; }
  &:disabled { opacity: .4; cursor: default; }
}
.bkp-seats-rail { --p: 0; padding-top: 6px; }
.bkp-seats-range {
  --t: 30px;
  display: block; width: 100%; height: var(--t); margin: 0; background: none; cursor: grab; -webkit-appearance: none; appearance: none; accent-color: var(--bkp-seats-b0);
  &:active { cursor: grabbing; }
  &::-webkit-slider-runnable-track {
    height: 14px; border-radius: 99px; box-shadow: inset 0 0 0 2px var(--bkp-seats-ink);
    background:
      linear-gradient(to right, transparent calc(var(--t) / 2 + var(--p) * (100% - var(--t))), color-mix(in oklch, var(--bkp-seats-card) 78%, transparent) 0),
      linear-gradient(to right, var(--bkp-seats-b0) 0 6.33%, var(--bkp-seats-b1) 0 33%, var(--bkp-seats-b2) 0);
  }
  &::-webkit-slider-thumb {
    -webkit-appearance: none; width: var(--t); height: var(--t); margin-top: -8px; border-radius: 50%;
    background: var(--bkp-seats-card); border: 3px solid var(--bkp-seats-ink); box-shadow: 0 3px 0 var(--bkp-seats-ink);
    transition: transform .3s var(--bkp-seats-pop);
  }
  &:active::-webkit-slider-thumb { transform: scale(1.15) rotate(-8deg); }
  &::-moz-range-track { height: 14px; border-radius: 99px; border: 2px solid var(--bkp-seats-ink); background: linear-gradient(to right, var(--bkp-seats-b0) 0 6.33%, var(--bkp-seats-b1) 0 33%, var(--bkp-seats-b2) 0); }
  &::-moz-range-thumb { width: 24px; height: 24px; border-radius: 50%; background: var(--bkp-seats-card); border: 3px solid var(--bkp-seats-ink); }
  &:focus-visible { outline: 3px solid var(--bkp-seats-b0); outline-offset: 6px; border-radius: 99px; }
}
.bkp-seats-scale {
  position: relative; height: 18px; margin: 6px 15px 0; font-size: 12px; font-weight: 700; color: var(--bkp-seats-muted); font-variant-numeric: tabular-nums;
  & span { position: absolute; left: calc((var(--v) - 1) / 150 * 100%); translate: -50% 0; }
  & span:last-child { translate: -80% 0; }
}

/* ---------- bill ---------- */
.bkp-seats-lines {
  display: grid; gap: 2px;
  & li { display: grid; grid-template-columns: 14px minmax(0, 1fr) auto 64px; align-items: center; gap: 10px; padding: 8px 0; font-variant-numeric: tabular-nums; transition: opacity .3s; }
  & li + li { border-top: 2px dotted var(--bkp-seats-line); }
  & i { width: 14px; height: 14px; border-radius: 50%; background: var(--b); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--b) 60%, var(--bkp-seats-ink)); }
  & small { font-size: 13px; font-weight: 600; color: var(--bkp-seats-muted); }
  & .bkp-seats-q { min-width: 3ch; padding: 1px 8px; border-radius: 99px; background: color-mix(in oklch, var(--b) 22%, transparent); font-size: 13px; font-weight: 750; text-align: center; }
  & b { text-align: right; font-weight: 800; }
  & li[data-zero] { opacity: .42; }
}
.bkp-seats-what { font-weight: 650; }
.bkp-seats-talk { display: none; padding: 12px 14px; border-radius: 14px; background: color-mix(in oklch, var(--bkp-seats-b2) 22%, var(--bkp-seats-card)); font-weight: 600; text-wrap: pretty; }
.bkp-seats-cta {
  display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 52px; padding: 0 18px; border: 0; border-radius: 99px; cursor: pointer;
  background: var(--bkp-seats-ink); color: var(--bkp-seats-paper); font-size: 16px; font-weight: 800;
  box-shadow: 0 4px 0 color-mix(in oklch, var(--bkp-seats-ink) 60%, var(--bkp-seats-b0));
  transition: transform .15s var(--bkp-seats-out), box-shadow .15s var(--bkp-seats-out);
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transition: transform .4s var(--bkp-seats-pop); }
  &:hover svg { transform: translateX(4px); }
  &:active { transform: translateY(4px); box-shadow: 0 0 0 transparent; }
  &:focus-visible { outline: 3px solid var(--bkp-seats-b0); outline-offset: 3px; }
}
.bkp-seats-fine { font-size: 13px; font-weight: 500; color: var(--bkp-seats-muted); text-align: center; text-wrap: balance; }

/* 150+ : swap the bill for a conversation */
.bkp-seats:has(.bkp-seats-range[data-talk]) {
  & .bkp-seats-lines { display: none; }
  & .bkp-seats-talk { display: block; }
  & .bkp-seats-total b { font-size: clamp(38px, 4.4cqi, 52px); }
}

@container (width < 520px) {
  .bkp-seats-sum { display: grid; grid-template-columns: auto 1fr; grid-template-areas: "k k" "count total" "plan total" "avg avg"; column-gap: 12px; }
  .bkp-seats-sum .bkp-seats-k { grid-area: k; }
  .bkp-seats-count { grid-area: count; }
  .bkp-seats-plan { grid-area: plan; }
  .bkp-seats-total { grid-area: total; justify-self: end; align-self: center; margin: 0; padding: 0; border: 0; }
  .bkp-seats-total b { font-size: 46px; }
  .bkp-seats-total small { display: none; }
  .bkp-seats-avg { grid-area: avg; margin-top: 10px; padding-top: 10px; border-top: 2px dashed var(--bkp-seats-line); }
  .bkp-seats-step { width: 40px; height: 40px; }
  .bkp-seats-lines li { grid-template-columns: 14px minmax(0, 1fr) auto 52px; gap: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-seats-s, .bkp-seats-s[data-on] { transition: background-color .2s, box-shadow .2s; transition-delay: 0s; }
  .bkp-seats-s::before, .bkp-seats-s::after, .bkp-seats-s[data-on]::before, .bkp-seats-s[data-on]::after { transition-delay: 0s; }
  .bkp-seats-s[data-on]::before { animation: none; }
  .bkp-seats-room[data-wave] .bkp-seats-s[data-on] { animation: none; }
  .bkp-seats-range::-webkit-slider-thumb, .bkp-seats-cta svg { transition: none; }
}

