/* Graduated per-seat pricing: [first seat, last seat, $ per seat]. */
const BANDS = [[1, 10, 8], [11, 50, 6], [51, 150, 4]];
const PLANS = [[10, 'Crew'], [50, 'Team'], [150, 'Company'], [Infinity, 'Enterprise']];
const MAX = 150;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const range = root.querySelector('.bkp-seats-range');
const room = root.querySelector('.bkp-seats-room');
const rail = root.querySelector('.bkp-seats-rail');
const out = root.querySelector('.bkp-seats-n');
const planSlot = root.querySelector('.bkp-seats-plan-slot');
const totalEl = root.querySelector('[data-total]');
const lines = [...root.querySelectorAll('.bkp-seats-lines li')];
const steps = [...root.querySelectorAll('.bkp-seats-step')];
const live = root.querySelector('[data-live]');
const cta = root.querySelector('[data-cta]');

/* 150 seats; a seat's band colours it, --r varies its tint and blink phase. */
let html = '';
for (let i = 0; i < MAX; i++) {
  const b = i < 10 ? 0 : i < 50 ? 1 : 2;
  const r = ((i * 0.6180339) % 1).toFixed(3);
  html += '<i class="bkp-seats-s" data-b="' + b + '" style="--r:' + r + '"></i>';
}
room.innerHTML = html;
const seats = [...room.children];

const price = (n) => BANDS.map(([lo, hi, rate]) => { const q = Math.max(0, Math.min(n, hi) - lo + 1); return { q, cost: q * rate }; });
const money = (v) => '$' + v.toLocaleString('en', { minimumFractionDigits: v % 1 ? 2 : 0, maximumFractionDigits: 2 });

let n = 0, shown = 0, raf = 0, liveT = 0;
function tween(to) {
  cancelAnimationFrame(raf);
  if (reduce.matches) { shown = to; totalEl.textContent = to.toLocaleString('en'); return; }
  const from = shown, t0 = performance.now();
  const tick = (now) => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / 320);
    shown = Math.round(from + (to - from) * (1 - (1 - k) ** 3));
    totalEl.textContent = shown.toLocaleString('en');
    if (k < 1) raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);
}

function swapPlan(name) {
  const old = planSlot.querySelector('b:not([data-leaving])');
  if (old.textContent === name) return;
  if (reduce.matches) { old.textContent = name; return; }
  const next = document.createElement('b');
  next.dataset.plan = '';
  next.textContent = name;
  planSlot.append(next);
  old.dataset.leaving = '';
  const rank = (t) => PLANS.findIndex((p) => p[1] === t);
  const dir = rank(name) > rank(old.textContent) ? 1 : -1;
  next.animate([{ transform: `translateY(${100 * dir}%)`, opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 520, easing: 'cubic-bezier(.2,.9,.3,1.25)' });
  old.animate([{ transform: 'none', opacity: 1 }, { transform: `translateY(${-100 * dir}%)`, opacity: 0 }], { duration: 320, easing: 'cubic-bezier(.4,0,1,1)' }).onfinish = () => old.remove();
}

function set(v, announce) {
  v = Math.max(1, Math.min(MAX + 1, Math.round(v)));
  const talk = v > MAX;
  const seatsOn = Math.min(v, MAX);
  /* Stagger only the seats that change, outward from the old edge, capped near 420ms in total. */
  const prev = Math.min(n || 0, MAX);
  const changed = Math.abs(seatsOn - prev) || 1;
  const gap = Math.min(16, 420 / changed);
  for (let i = Math.min(prev, seatsOn); i < Math.max(prev, seatsOn); i++) {
    const s = seats[i];
    const d = seatsOn > prev ? i - prev : prev - 1 - i;
    s.style.setProperty('--d', Math.round(d * gap));
    s.toggleAttribute('data-on', i < seatsOn);
  }
  n = v;
  range.value = v;
  range.toggleAttribute('data-talk', talk);
  rail.style.setProperty('--p', (v - 1) / MAX);
  range.style.setProperty('--p', (v - 1) / MAX);
  range.setAttribute('aria-valuetext', talk ? 'More than 150 people' : v + (v === 1 ? ' person' : ' people'));
  out.textContent = talk ? '150+' : v;
  root.querySelector('[data-people]').textContent = v === 1 ? 'person' : 'people';
  steps[0].disabled = v <= 1;
  steps[1].disabled = talk;
  swapPlan(PLANS.find(([hi]) => v <= hi)[1]);

  const parts = price(seatsOn);
  const total = parts.reduce((s, p) => s + p.cost, 0);
  parts.forEach((p, i) => {
    lines[i].querySelector('[data-q]').textContent = p.q;
    lines[i].querySelector('[data-c]').textContent = money(p.cost);
    lines[i].toggleAttribute('data-zero', p.q === 0);
  });
  if (talk) {
    cancelAnimationFrame(raf);
    root.querySelector('.bkp-seats-cur').hidden = true;
    root.querySelector('.bkp-seats-total small').hidden = true;
    totalEl.textContent = 'Let’s talk';
    root.querySelector('[data-avg]').textContent = 'Volume pricing below $4 a person';
    cta.textContent = 'Book a 20-minute call';
  } else {
    root.querySelector('.bkp-seats-cur').hidden = false;
    root.querySelector('.bkp-seats-total small').hidden = false;
    if (!/^\d/.test(totalEl.textContent)) shown = total;
    tween(total);
    root.querySelector('[data-avg]').textContent = v === 1 ? 'Just you — $8 a month' : 'That’s ' + money(Math.round((total / v) * 100) / 100) + ' a person, on average';
    cta.textContent = 'Start a free month for ' + v;
  }
  if (announce) {
    clearTimeout(liveT);
    liveT = setTimeout(() => {
      live.textContent = talk ? 'More than 150 people: contact us for volume pricing.' : v + (v === 1 ? ' person, ' : ' people, ') + money(total) + ' a month.';
    }, 450);
  }
}

range.addEventListener('input', () => set(+range.value, true));
steps.forEach((b) => b.addEventListener('click', () => set(n + +b.dataset.d, true)));

/* The CTA cheers: a Mexican wave across the seats that are taken. */
root.querySelector('.bkp-seats-cta').addEventListener('click', () => {
  live.textContent = n > MAX ? 'We will email you to book a call.' : 'Starting a free month for ' + n + ' people.';
  if (reduce.matches) return;
  const cols = parseInt(getComputedStyle(room).getPropertyValue('--cols'), 10) || 15;
  seats.forEach((s, i) => s.style.setProperty('--w', (i % cols) * 28 + Math.floor(i / cols) * 40));
  room.removeAttribute('data-wave');
  void room.offsetWidth;
  room.setAttribute('data-wave', '');
  clearTimeout(room._t);
  room._t = setTimeout(() => room.removeAttribute('data-wave'), 1800);
});

/* Pause the idle blinking when the section is off screen. */
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle('is-off', !es[es.length - 1].isIntersecting);
});
io.observe(root);

shown = 0;
set(+range.value, false);

