@property --bkp-credits-a { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --bkp-credits-b { syntax: "<number>"; inherits: true; initial-value: 0; }

.bkp-credits {
  /* re-theme: override these four */
  --bkp-credits-bg: oklch(16.5% 0.024 20);
  --bkp-credits-ink: oklch(93.5% 0.022 85);
  --bkp-credits-gold: oklch(81% 0.105 78);
  --bkp-credits-panel: oklch(19.5% 0.028 20);

  --bkp-credits-muted: color-mix(in oklch, var(--bkp-credits-ink) 58%, var(--bkp-credits-bg));
  --bkp-credits-faint: color-mix(in oklch, var(--bkp-credits-ink) 34%, var(--bkp-credits-bg));
  --bkp-credits-hair: color-mix(in oklch, var(--bkp-credits-gold) 22%, transparent);
  --bkp-credits-pale: color-mix(in oklch, var(--bkp-credits-gold) 55%, white);
  --bkp-credits-deep: color-mix(in oklch, var(--bkp-credits-gold) 42%, var(--bkp-credits-bg));
  --bkp-credits-serif: Didot, "Bodoni 72", "Bodoni MT", ui-serif, "Iowan Old Style", Georgia, serif;
  --bkp-credits-slosh: linear(0, .02 2%, .1 5%, .32 10%, .62 17%, .86 25%, 1.03 33%, 1.07 39%, 1.06 45%, 1.01 54%, .985 62%, .99 72%, 1.003 85%, 1);
  --bkp-credits-out: cubic-bezier(.19, 1, .22, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(50% 60% at 50% 100%, color-mix(in oklch, var(--bkp-credits-gold) 9%, transparent), transparent 70%),
    var(--bkp-credits-bg);
  color: var(--bkp-credits-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, ol, figure, fieldset, legend, figcaption) { margin: 0; padding: 0; border: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; }
}
.bkp-credits-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-credits-in { max-width: 1180px; margin-inline: auto; padding: clamp(40px, 6.5cqi, 88px) clamp(16px, 4cqi, 48px); }
.bkp-credits-k { font-size: 11px; font-weight: 600; letter-spacing: .22em; text-transform: uppercase; color: var(--bkp-credits-muted); }

/* ---------- header ---------- */
.bkp-credits-head { display: grid; gap: 16px; max-width: 820px; }
.bkp-credits-brand {
  display: flex; align-items: center; gap: 10px; font-size: 12px; font-weight: 600; letter-spacing: .3em; text-transform: uppercase;
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--bkp-credits-gold); stroke-width: 1.3; stroke-linejoin: round; stroke-linecap: round; }
  & span { color: var(--bkp-credits-gold); }
}
.bkp-credits-title {
  font: 400 clamp(36px, 5.6cqi, 70px)/1 var(--bkp-credits-serif); letter-spacing: -.01em; text-wrap: balance;
  & em { color: var(--bkp-credits-gold); }
}
.bkp-credits-lede { max-width: 54ch; color: var(--bkp-credits-muted); font-size: clamp(15px, 1.45cqi, 17px); text-wrap: pretty; }

/* ---------- body ---------- */
.bkp-credits-body {
  --bkp-credits-a: 0; --bkp-credits-b: 0;
  display: grid; grid-template-columns: 104px minmax(0, 1fr); grid-template-areas: "vessel buys" "packs packs" "checkout checkout";
  gap: 26px 18px; margin-top: clamp(30px, 4.5cqi, 54px);
  transition: --bkp-credits-a 1.5s var(--bkp-credits-slosh), --bkp-credits-b 1.5s var(--bkp-credits-slosh) .12s;
}
@container (width >= 940px) {
  .bkp-credits-body { grid-template-columns: minmax(0, 1.12fr) auto minmax(0, 1fr); grid-template-areas: "packs vessel buys" "packs vessel checkout"; column-gap: clamp(30px, 4.5cqi, 60px); align-items: start; }
}

/* ---------- packs: a menu card ---------- */
.bkp-credits-packs { grid-area: packs; display: grid; align-content: start;
  & legend { margin-bottom: 10px; }
  & label {
    position: relative; display: grid; grid-template-columns: 22px auto minmax(18px, 1fr) auto; grid-template-areas: "dot qty lead price" ". sub sub unit";
    column-gap: 10px; align-items: baseline; padding: 15px 14px 14px; border-top: 1px solid var(--bkp-credits-hair); cursor: pointer;
    transition: background-color .4s var(--bkp-credits-out), box-shadow .4s var(--bkp-credits-out);
    @starting-style { opacity: 0; translate: -10px 0; }
    transition-property: background-color, box-shadow, opacity, translate; transition-duration: .4s, .4s, .7s, .9s; transition-delay: 0s, 0s, calc(var(--i) * 80ms), calc(var(--i) * 80ms);
  }
  & label:last-of-type { border-bottom: 1px solid var(--bkp-credits-hair); }
  & label:hover { background: color-mix(in oklch, var(--bkp-credits-gold) 5%, transparent); }
  & label:has(input:checked) { background: linear-gradient(90deg, color-mix(in oklch, var(--bkp-credits-gold) 13%, transparent), transparent 85%); box-shadow: inset 2px 0 0 var(--bkp-credits-gold); }
  & label:has(input:focus-visible) { outline: 1.5px solid var(--bkp-credits-gold); outline-offset: -1.5px; }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
}
.bkp-credits-dot {
  grid-area: dot; align-self: center; width: 14px; height: 14px; border-radius: 50%; box-shadow: inset 0 0 0 1.25px var(--bkp-credits-faint);
  display: grid; place-items: center; transition: box-shadow .3s;
  &::after { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--bkp-credits-gold); transform: scale(0); transition: transform .45s var(--bkp-credits-slosh); }
}
.bkp-credits-packs label:has(input:checked) .bkp-credits-dot { box-shadow: inset 0 0 0 1.25px var(--bkp-credits-gold); &::after { transform: scale(1); } }
.bkp-credits-qty { grid-area: qty; font-size: 14px; color: var(--bkp-credits-muted); white-space: nowrap;
  & b { margin-right: 4px; font: 400 clamp(24px, 2.4cqi, 30px)/1 var(--bkp-credits-serif); color: var(--bkp-credits-ink); font-variant-numeric: tabular-nums lining-nums; }
  & em { margin-left: 6px; font: italic 400 14px/1 var(--bkp-credits-serif); color: var(--bkp-credits-gold); }
}
.bkp-credits-lead { grid-area: lead; align-self: end; margin-bottom: .45em; border-bottom: 1px dotted var(--bkp-credits-faint); }
.bkp-credits-price { grid-area: price; font: 400 clamp(22px, 2.2cqi, 26px)/1 var(--bkp-credits-serif); font-variant-numeric: tabular-nums lining-nums; }
.bkp-credits-sub, .bkp-credits-unit { margin-top: 5px; font-size: 12.5px; color: var(--bkp-credits-faint); font-variant-numeric: tabular-nums; }
.bkp-credits-sub { grid-area: sub; }
.bkp-credits-unit { grid-area: unit; text-align: right; }
.bkp-credits-packs label:has(input:checked) :is(.bkp-credits-sub, .bkp-credits-unit) { color: var(--bkp-credits-gold); }

/* ---------- the vessel ---------- */
.bkp-credits-vessel { grid-area: vessel; display: grid; justify-items: center; align-content: start; gap: 14px; padding-right: 26px; }
.bkp-credits-glass {
  position: relative; width: clamp(66px, 11cqi, 132px); height: clamp(260px, 36cqi, 420px);
  border-radius: 40px 40px 26px 26px / 22px 22px 26px 26px;
  background: linear-gradient(90deg, color-mix(in oklch, var(--bkp-credits-ink) 7%, transparent), transparent 30%, transparent 70%, color-mix(in oklch, var(--bkp-credits-ink) 5%, transparent));
  box-shadow: inset 0 0 0 1.25px color-mix(in oklch, var(--bkp-credits-gold) 46%, transparent), 0 30px 60px -30px color-mix(in oklch, var(--bkp-credits-gold) 35%, transparent);
  &::after { /* glass highlights over the liquid */
    content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 3;
    background: linear-gradient(90deg, transparent 10%, color-mix(in oklch, white 30%, transparent) 15%, transparent 22%, transparent 80%, color-mix(in oklch, white 12%, transparent) 86%, transparent 90%);
  }
}
.bkp-credits-well { position: absolute; inset: 0; border-radius: inherit; overflow: clip; }
.bkp-credits-liquid {
  position: absolute; inset: 0;
  transform: translateY(calc((1 - var(--lvl)) * 100%));
  & svg { position: absolute; left: 0; bottom: calc(100% - 1px); width: 200%; height: 12px; fill: currentColor; animation: bkp-credits-wave 5.5s linear infinite; }
}
.bkp-credits-base {
  --lvl: var(--bkp-credits-a); z-index: 2; color: var(--bkp-credits-gold);
  background: linear-gradient(to bottom, var(--bkp-credits-gold), var(--bkp-credits-deep) 85%);
}
.bkp-credits-bonus {
  --lvl: var(--bkp-credits-b); z-index: 1; color: var(--bkp-credits-pale);
  background:
    radial-gradient(circle, color-mix(in oklch, white 75%, transparent) 0 .8px, transparent 1.4px) 0 0 / 11px 13px,
    linear-gradient(to bottom, var(--bkp-credits-pale), color-mix(in oklch, var(--bkp-credits-pale) 70%, var(--bkp-credits-gold)));
  & svg { animation-duration: 8s; animation-direction: reverse; }
}
@keyframes bkp-credits-wave { to { transform: translateX(-50%); } }
.bkp-credits-fizz {
