}
.bkp-credits-or { margin-top: 10px; font: italic 400 15px/1.4 var(--bkp-credits-serif); color: var(--bkp-credits-muted); }

/* ---------- checkout ---------- */
.bkp-credits-checkout { grid-area: checkout; display: grid; gap: 14px; }
