  & b { color: var(--bkp-credits-ink); font-weight: 600; margin-right: 4px; }
}
.bkp-credits-switch {
  position: relative; width: 40px; height: 22px; margin-top: 1px; padding: 0; border: 0; border-radius: 99px; cursor: pointer;
  background: color-mix(in oklch, var(--bkp-credits-ink) 14%, transparent); transition: background-color .3s;
  & i { position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: var(--bkp-credits-ink); transition: translate .45s var(--bkp-credits-slosh), background-color .3s; }
  &[aria-checked="true"] { background: var(--bkp-credits-gold); & i { translate: 18px 0; background: var(--bkp-credits-bg); } }
  &:focus-visible { outline: 1.5px solid var(--bkp-credits-gold); outline-offset: 3px; }
}
.bkp-credits-cta {
  position: relative; overflow: hidden; min-height: 54px; padding: 0 20px; border: 0; border-radius: 2px; cursor: pointer;
  background: linear-gradient(180deg, var(--bkp-credits-pale), var(--bkp-credits-gold)); color: var(--bkp-credits-bg);
  font-size: 13px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; font-variant-numeric: tabular-nums;
  transition: transform .2s var(--bkp-credits-out), box-shadow .3s;
  &::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, color-mix(in oklch, white 55%, transparent) 50%, transparent 70%); transform: translateX(-110%); transition: transform .9s var(--bkp-credits-out); }
  &:hover { box-shadow: 0 14px 30px -16px var(--bkp-credits-gold); &::after { transform: translateX(110%); } }
  &:active { transform: scale(.985); }
  &:focus-visible { outline: 1.5px solid var(--bkp-credits-gold); outline-offset: 3px; }
  & span { position: relative; z-index: 1; }
}
.bkp-credits-fine { font-size: 12px; color: var(--bkp-credits-faint); text-align: center; }

@container (width < 560px) {
  .bkp-credits-vessel { padding-right: 22px; }
  .bkp-credits-buys .bkp-credits-k { letter-spacing: .14em; }
  .bkp-credits-list li { grid-template-columns: minmax(0, 1fr) auto; gap: 8px; }
