  .bkp-credits-packs label { padding-inline: 10px; column-gap: 8px; }
  .bkp-credits-qty em { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-credits-body { transition: none; }
  .bkp-credits-liquid svg, .bkp-credits-fizz i { animation: none; }
