const CAP = 8000;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 8);
const radios = [...root.querySelectorAll('.bkp-credits-packs input')];
radios.forEach((r) => { r.name = r.name + '-' + uid; });
const body = root.querySelector('.bkp-credits-body');
const values = [...root.querySelectorAll('[data-cost]')];
const totals = [...root.querySelectorAll('[data-total]')];
const sw = root.querySelector('.bkp-credits-switch');
const autoText = root.querySelector('[data-auto]');
const ctaBtn = root.querySelector('.bkp-credits-cta');
const ctaText = root.querySelector('[data-cta]');
const live = root.querySelector('[data-live]');
const fmt = (n) => Math.floor(n).toLocaleString('en');
const clock = (s) => { s = Math.floor(s); const m = Math.floor(s / 60); return m ? m + ' min ' + (s % 60) + ' s' : s + ' s'; };

let shown = 0, target = 0, raf = 0;
function paint(credits) {
  totals.forEach((el) => { el.textContent = fmt(credits); });
  values.forEach((el) => {
    const per = +el.dataset.cost;
    el.textContent = 'time' in el.dataset ? clock(credits / per) : fmt(credits / per);
  });
}
function tween(to) {
  cancelAnimationFrame(raf);
  target = to;
  if (reduce.matches || shown === 0) { shown = to; paint(to); return; }
  const from = shown, t0 = performance.now(), dur = 900;
  const tick = (now) => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / dur), e = 1 - (1 - k) ** 4;
    shown = from + (to - from) * e;
    paint(shown);
    if (k < 1) raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);
}

const pack = () => {
  const r = radios.find((x) => x.checked);
  const base = +r.dataset.base, bonus = +r.dataset.bonus;
  return { base, bonus, total: base + bonus, price: +r.dataset.price };
};
function autoCopy(p) {
  autoText.textContent = sw.getAttribute('aria-checked') === 'true'
    ? 'On — when your balance drops below 300 credits we add another ' + fmt(p.total) + ' for $' + p.price + '.'
    : 'Off — top up by hand whenever you like.';
}
function render(announce) {
  const p = pack();
  body.style.setProperty('--bkp-credits-a', (p.base / CAP).toFixed(4));
  body.style.setProperty('--bkp-credits-b', (p.total / CAP).toFixed(4));
  tween(p.total);
  ctaText.textContent = 'Buy ' + fmt(p.total) + ' credits · $' + p.price;
  autoCopy(p);
  if (announce) live.textContent = fmt(p.total) + ' credits for $' + p.price + (p.bonus ? ', including ' + fmt(p.bonus) + ' bonus.' : '.');
}

root.addEventListener('change', (e) => { if (radios.includes(e.target)) render(true); });
sw.addEventListener('click', () => {
  sw.setAttribute('aria-checked', String(sw.getAttribute('aria-checked') !== 'true'));
  autoCopy(pack());
});

/* The CTA pours: the surface swells and the fizz quickens, then settles. */
ctaBtn.addEventListener('click', () => {
  const p = pack();
  live.textContent = fmt(p.total) + ' credits added to checkout.';
  ctaText.textContent = 'Added — ' + fmt(p.total) + ' credits at checkout';
  clearTimeout(ctaBtn._t);
  ctaBtn._t = setTimeout(() => { ctaText.textContent = 'Buy ' + fmt(pack().total) + ' credits · $' + pack().price; }, 2600);
  if (reduce.matches) return;
  root.querySelectorAll('.bkp-credits-liquid svg').forEach((s, i) => s.animate(
    [{ scale: '1 1' }, { scale: '1 2.6' }, { scale: '1 .7' }, { scale: '1 1' }],
    { duration: 1300, delay: i * 90, easing: 'cubic-bezier(.3,.7,.3,1)', composite: 'add' }));
  root.querySelector('.bkp-credits-well').animate(
    [{ transform: 'none' }, { transform: 'rotate(-1.4deg)' }, { transform: 'rotate(1deg)' }, { transform: 'none' }],
    { duration: 1100, easing: 'ease-in-out' });
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle('is-off', !es[es.length - 1].isIntersecting);
});
io.observe(root);

/* Fill from empty on first paint. */
paint(pack().total);
shown = pack().total;
requestAnimationFrame(() => { if (!root.isConnected) return; render(false); });

