.bkp-addons {
  /* re-theme: paper, ink and the six module colours */
  --bkp-addons-paper: oklch(91% 0.006 95);
  --bkp-addons-ink: oklch(16% 0 0);
  --bkp-addons-c1: oklch(89% 0.175 100);
  --bkp-addons-c2: oklch(76% 0.17 148);
  --bkp-addons-c3: oklch(50% 0.2 262);
  --bkp-addons-c4: oklch(79% 0.12 355);
  --bkp-addons-c5: oklch(60% 0.22 29);
  --bkp-addons-c6: oklch(76% 0.16 58);

  --bkp-addons-sheet: color-mix(in oklch, var(--bkp-addons-paper) 45%, white);
  --bkp-addons-muted: color-mix(in oklch, var(--bkp-addons-ink) 66%, var(--bkp-addons-paper));
  --bkp-addons-k: 1.6px; /* tower pixels per dollar */
  --bkp-addons-b: 3px;
  --bkp-addons-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkp-addons-snap: cubic-bezier(.2, 1.4, .4, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    linear-gradient(color-mix(in oklch, var(--bkp-addons-ink) 7%, transparent) 1px, transparent 1px) 0 0 / 24px 24px,
    linear-gradient(90deg, color-mix(in oklch, var(--bkp-addons-ink) 7%, transparent) 1px, transparent 1px) 0 0 / 24px 24px,
    var(--bkp-addons-paper);
  color: var(--bkp-addons-ink);
  font: 400 14px/1.45 var(--bkp-addons-mono);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p) { margin: 0; }
  & :where(button) { font: inherit; color: inherit; }
}
.bkp-addons-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-addons-in { max-width: 1180px; margin-inline: auto; padding: clamp(36px, 6cqi, 80px) clamp(16px, 4cqi, 48px); }
.bkp-addons-k { font-size: 12px; font-weight: 700; letter-spacing: .08em;
  & span { float: right; font-weight: 400; color: var(--bkp-addons-muted); }
}

/* ---------- header ---------- */
.bkp-addons-head { display: grid; gap: 16px; }
.bkp-addons-brand {
  display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 800; letter-spacing: .06em;
  & svg { width: 24px; height: 24px; fill: var(--bkp-addons-c1); stroke: var(--bkp-addons-ink); stroke-width: 1.6; stroke-linejoin: miter; }
  & span { font-weight: 400; color: var(--bkp-addons-muted); }
}
.bkp-addons-title {
  max-width: 13ch; font: 900 clamp(40px, 7.6cqi, 100px)/.88 system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: -.045em; text-transform: uppercase; text-wrap: balance;
  /* the highlighter band covers only the cap height, so a lower line never paints over the one above */
  & span { display: inline; padding: 0 .08em; background: linear-gradient(var(--bkp-addons-c1), var(--bkp-addons-c1)) 0 88% / 100% 68% no-repeat; box-decoration-break: clone; -webkit-box-decoration-break: clone; }
}
.bkp-addons-lede { max-width: 60ch; font-size: clamp(13.5px, 1.3cqi, 15px); text-wrap: pretty; }
@container (width >= 900px) {
  .bkp-addons-head { grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); grid-template-areas: "brand brand" "title lede"; align-items: end; column-gap: 40px; }
  .bkp-addons-brand { grid-area: brand; }
  .bkp-addons-title { grid-area: title; }
  .bkp-addons-lede { grid-area: lede; padding: 14px 16px; border: var(--bkp-addons-b) solid var(--bkp-addons-ink); background: var(--bkp-addons-sheet); }
}

/* ---------- board ---------- */
.bkp-addons-board { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "out" "tiles"; gap: 22px; margin-top: clamp(26px, 4cqi, 44px); }
@container (width >= 780px) { .bkp-addons-board { grid-template-columns: minmax(0, 1.55fr) minmax(280px, 1fr); grid-template-areas: "tiles out"; align-items: start; } }

/* ---------- tiles ---------- */
.bkp-addons-tiles { grid-area: tiles; display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; }
@container (width >= 520px) { .bkp-addons-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; } }
.bkp-addons-tile {
  position: relative; display: grid; grid-template-columns: 1fr auto; grid-template-areas: "name sw" "desc desc" "price price";
  align-content: start; gap: 6px 10px; min-height: 148px; padding: 16px; cursor: pointer;
  border: var(--bkp-addons-b) solid var(--bkp-addons-ink); background: var(--bkp-addons-sheet);
  box-shadow: 6px 6px 0 var(--bkp-addons-ink);
  transition: transform .14s var(--bkp-addons-snap), box-shadow .14s var(--bkp-addons-snap), background-color .18s, color .18s;
  & input { position: absolute; opacity: 0; width: 1px; height: 1px; margin: 0; pointer-events: none; }
  & b { grid-area: name; font-size: 15px; font-weight: 800; text-transform: uppercase; letter-spacing: .02em; }
  &:hover { transform: translate(-2px, -2px); box-shadow: 8px 8px 0 var(--bkp-addons-ink); }
  &:active { transform: translate(3px, 3px); box-shadow: 3px 3px 0 var(--bkp-addons-ink); }
  &:has(input:checked) { background: var(--c); color: var(--fg); transform: translate(6px, 6px); box-shadow: 0 0 0 var(--bkp-addons-ink); }
  &:has(input:focus-visible) { outline: 3px dashed var(--bkp-addons-ink); outline-offset: 5px; }
}
.bkp-addons-sw {
  grid-area: sw; display: grid; place-items: center; width: 30px; height: 30px; border: var(--bkp-addons-b) solid var(--bkp-addons-ink); background: var(--c);
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--fg); stroke-width: 3; stroke-linecap: square; stroke-dasharray: 22; stroke-dashoffset: 22; transition: stroke-dashoffset .25s ease-out; }
}
.bkp-addons-tile:has(input:checked) .bkp-addons-sw { background: var(--bkp-addons-sheet); & svg { stroke: var(--bkp-addons-ink); stroke-dashoffset: 0; } }
.bkp-addons-desc { grid-area: desc; font-size: 13px; line-height: 1.4; text-wrap: pretty; opacity: .85; }
.bkp-addons-price { grid-area: price; align-self: end; margin-top: 8px; font: 900 26px/1 system-ui, -apple-system, sans-serif; letter-spacing: -.03em; font-variant-numeric: tabular-nums;
  & small { margin-left: 3px; font: 700 11px/1 var(--bkp-addons-mono); letter-spacing: .06em; }
}

/* ---------- the stack ---------- */
.bkp-addons-out {
  grid-area: out; display: grid; gap: 14px; padding: 16px; border: var(--bkp-addons-b) solid var(--bkp-addons-ink); background: var(--bkp-addons-sheet);
  box-shadow: 8px 8px 0 var(--bkp-addons-ink);
}
.bkp-addons-yard { position: relative; display: grid; grid-template-columns: 44px minmax(0, 1fr); height: calc(240 * var(--bkp-addons-k) + 6px); }
.bkp-addons-ruler {
  position: relative; border-right: 1.5px solid var(--bkp-addons-ink);
  & span { position: absolute; right: 6px; bottom: calc(var(--m) * var(--bkp-addons-k) + 6px); translate: 0 50%; font-size: 10.5px; color: var(--bkp-addons-muted); font-variant-numeric: tabular-nums; }
  & span::after { content: ""; position: absolute; left: calc(100% + 1px); top: 50%; width: 6px; height: 1.5px; background: var(--bkp-addons-ink); }
}
.bkp-addons-tower {
  position: relative; display: flex; flex-direction: column-reverse; justify-content: flex-start; padding: 0 0 0 12px;
  border-bottom: 6px solid var(--bkp-addons-ink);
}
.bkp-addons-block {
  container-type: inline-size;
  display: flex; align-items: center; justify-content: space-between; gap: 6px; flex: none; height: calc(var(--v) * var(--bkp-addons-k)); padding: 0 10px;
  border: var(--bkp-addons-b) solid var(--bkp-addons-ink); border-bottom: 0; background: var(--c); color: var(--fg);
  font-size: 11.5px; font-weight: 800; letter-spacing: .04em; white-space: nowrap; overflow: hidden;
  & b { font-variant-numeric: tabular-nums; }
}
@container (width < 120px) { .bkp-addons-block span { display: none; } }
@container (width < 34px) { .bkp-addons-block b { display: none; } }
.bkp-addons-ghost { position: absolute; z-index: 2; margin: 0; pointer-events: none; }

.bkp-addons-total { display: grid; grid-template-columns: 1fr auto; align-items: end; gap: 0 12px; padding-top: 10px; border-top: var(--bkp-addons-b) solid var(--bkp-addons-ink);
  & .bkp-addons-k { grid-column: 1 / -1; }
}
.bkp-addons-big { display: flex; align-items: flex-start; font: 900 clamp(56px, 7cqi, 84px)/.9 system-ui, -apple-system, sans-serif; letter-spacing: -.05em; font-variant-numeric: tabular-nums;
  & span { font-size: .45em; line-height: 1.15; margin-right: 2px; }
}
.bkp-addons-sum { justify-self: end; max-width: 22ch; padding-bottom: 6px; font-size: 12px; color: var(--bkp-addons-muted); text-align: right; font-variant-numeric: tabular-nums; }
.bkp-addons-actions { display: grid; grid-template-columns: auto 1fr; gap: 10px; }
.bkp-addons-clear, .bkp-addons-cta {
  min-height: 48px; padding: 0 14px; border: var(--bkp-addons-b) solid var(--bkp-addons-ink); cursor: pointer; font-weight: 800; letter-spacing: .06em;
  box-shadow: 4px 4px 0 var(--bkp-addons-ink); transition: transform .12s var(--bkp-addons-snap), box-shadow .12s var(--bkp-addons-snap);
  &:hover { transform: translate(-1px, -1px); box-shadow: 5px 5px 0 var(--bkp-addons-ink); }
  &:active { transform: translate(4px, 4px); box-shadow: 0 0 0 var(--bkp-addons-ink); }
  &:focus-visible { outline: 3px dashed var(--bkp-addons-ink); outline-offset: 4px; }
}
.bkp-addons-clear { background: var(--bkp-addons-sheet); &:disabled { opacity: .45; cursor: default; transform: none; box-shadow: 4px 4px 0 var(--bkp-addons-ink); } }
.bkp-addons-cta { display: flex; align-items: center; justify-content: center; gap: 10px; background: var(--bkp-addons-c1);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: square; }
}

/* ---------- narrow: the tower lies down as one proportional bar ---------- */
@container (width < 780px) {
  .bkp-addons-yard { grid-template-columns: minmax(0, 1fr); height: auto; }
  .bkp-addons-ruler { display: none; }
  .bkp-addons-tower { flex-direction: row; height: 64px; padding: 0; border-bottom: 0; border-left: 0; border-right: var(--bkp-addons-b) solid var(--bkp-addons-ink); }
  .bkp-addons-block { flex: var(--v) 1 0; height: auto; min-width: 0; padding: 0 6px; border-bottom: var(--bkp-addons-b) solid var(--bkp-addons-ink); border-right: 0; flex-direction: column; justify-content: center; align-items: flex-start; gap: 2px; }
  .bkp-addons-sum { max-width: none; }
}
@container (width < 520px) {
  .bkp-addons-tile { min-height: 0; padding: 14px; }
  .bkp-addons-cta { font-size: 12.5px; letter-spacing: .02em; }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-addons-tile, .bkp-addons-clear, .bkp-addons-cta { transition: background-color .15s, color .15s; }
  .bkp-addons-tile:hover, .bkp-addons-tile:active { transform: none; }
  .bkp-addons-tile:has(input:checked) { transform: none; box-shadow: 0 0 0 var(--bkp-addons-b) var(--bkp-addons-ink); }
  .bkp-addons-sw svg { transition: none; }
}

