const BASE = 49;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const tower = root.querySelector('.bkp-addons-tower');
const tiles = root.querySelector('.bkp-addons-tiles');
const boxes = [...tiles.querySelectorAll('input')];
const totalEl = root.querySelector('[data-total]');
const sumEl = root.querySelector('[data-sum]');
const countEl = root.querySelector('[data-count]');
const clearBtn = root.querySelector('.bkp-addons-clear');
const live = root.querySelector('[data-live]');
const ctaText = root.querySelector('[data-cta]');
/* Gravity: fall, hit, two short bounces. */
const BOUNCE = 'linear(0, .063, .25 12.5%, .563, 1 25%, .891 30%, .813, .766, .75 37.5%, .766, .813, .891 45%, 1 50%, .973, .953, .941, .938 56.25%, .941, .953, .973, 1 62.5%, .993, .988, .985, .984 68.75%, .985, .988, .993, 1 75%, 1)';
const order = [];  /* stacking order: keys in the order they were added */

const blockFor = (box) => {
  const tile = box.closest('.bkp-addons-tile');
  const el = document.createElement('div');
  el.className = 'bkp-addons-block';
  el.dataset.key = box.dataset.key;
  el.style.cssText = '--v:' + box.dataset.price + ';--c:' + tile.style.getPropertyValue('--c') + ';--fg:' + tile.style.getPropertyValue('--fg');
  el.innerHTML = '<span>' + box.dataset.name + '</span><b>$' + box.dataset.price + '</b>';
  return el;
};
const vertical = () => getComputedStyle(tower).flexDirection.startsWith('column');
const rects = () => new Map([...tower.children].filter((b) => !b.classList.contains('bkp-addons-ghost')).map((b) => [b.dataset.key, b.getBoundingClientRect()]));

/* FLIP every block that moved; drop the new one in from above (or slide it in from the right when the bar lies flat). */
function flip(before, added) {
  if (reduce.matches) return;
  const vert = vertical();
  [...tower.children].forEach((b) => {
    if (b.classList.contains('bkp-addons-ghost')) return;
    const now = b.getBoundingClientRect();
    if (b === added) {
      const lift = vert ? -(now.top - tower.getBoundingClientRect().top + now.height + 40) : 0;
      b.animate(vert
        ? [{ transform: 'translateY(' + lift + 'px)' }, { transform: 'none' }]
        : [{ transform: 'translateX(40%)', opacity: 0 }, { transform: 'none', opacity: 1 }],
        { duration: vert ? 760 : 420, easing: vert ? BOUNCE : 'cubic-bezier(.2,1.3,.4,1)' });
      return;
    }
    const was = before.get(b.dataset.key);
    if (!was) return;
    const dx = was.left - now.left, dy = was.top - now.top;
    if (!dx && !dy && was.width === now.width) return;
    const sx = was.width / now.width;
    b.animate([{ transformOrigin: '0 0', transform: 'translate(' + dx + 'px,' + dy + 'px) scaleX(' + sx + ')' }, { transformOrigin: '0 0', transform: 'none' }],
      { duration: vert ? 640 : 420, easing: vert && dy < 0 ? BOUNCE : 'cubic-bezier(.2,1.2,.4,1)' });
  });
}
/* A removed block leaves a ghost in place that gets knocked off the stack. */
function ghost(block, i) {
  if (reduce.matches) return;
  const r = block.getBoundingClientRect(), t = tower.getBoundingClientRect();
  const g = block.cloneNode(true);
  g.classList.add('bkp-addons-ghost');
  g.style.left = r.left - t.left + 'px';
  g.style.top = r.top - t.top + 'px';
  g.style.width = r.width + 'px';
  g.style.height = r.height + 'px';
  g.style.flex = 'none';
  tower.append(g);
  g.animate([{ transform: 'none', opacity: 1 }, { transform: 'translate(70%, -18px) rotate(14deg)', opacity: 0 }],
    { duration: 380, delay: i * 50, easing: 'cubic-bezier(.5,0,.75,0)', fill: 'forwards' }).onfinish = () => g.remove();
}

let shown = 0, raf = 0;
function tween(to) {
  cancelAnimationFrame(raf);
  if (reduce.matches || !shown) { shown = to; totalEl.textContent = to; return; }
  const from = shown, t0 = performance.now();
  const tick = (now) => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / 360);
    shown = Math.round(from + (to - from) * (1 - (1 - k) ** 3));
    totalEl.textContent = shown;
    if (k < 1) raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);
}

function summarise(announce) {
  const parts = [BASE, ...order.map((k) => +boxes.find((b) => b.dataset.key === k).dataset.price)];
  const total = parts.reduce((a, b) => a + b, 0);
  tween(total);
  sumEl.textContent = parts.length > 1 ? parts.join(' + ') + ' = ' + total : 'CORE ONLY = ' + total;
  countEl.textContent = parts.length + (parts.length === 1 ? ' MODULE' : ' MODULES');
  clearBtn.disabled = order.length === 0;
  ctaText.textContent = 'START 14-DAY TRIAL';
  if (announce) live.textContent = announce + ' Total $' + total + ' a month.';
}

function toggle(box) {
  const key = box.dataset.key;
  const before = rects();
  let added = null;
  if (box.checked && !order.includes(key)) {
    order.push(key);
    added = blockFor(box);
    tower.append(added);
  } else if (!box.checked && order.includes(key)) {
    order.splice(order.indexOf(key), 1);
    const el = tower.querySelector('[data-key="' + key + '"]:not(.bkp-addons-ghost)');
    ghost(el, 0);
    el.remove();
  }
  flip(before, added);
  summarise((box.checked ? 'Added ' : 'Removed ') + box.dataset.name.toLowerCase() + '.');
}

tiles.addEventListener('change', (e) => { if (boxes.includes(e.target)) toggle(e.target); });

/* Arrow keys move between modules, following the grid's current column count. */
tiles.addEventListener('keydown', (e) => {
  const i = boxes.indexOf(document.activeElement);
  if (i < 0) return;
  const cols = getComputedStyle(tiles).gridTemplateColumns.split(' ').length;
  const j = { ArrowRight: i + 1, ArrowLeft: i - 1, ArrowDown: i + cols, ArrowUp: i - cols, Home: 0, End: boxes.length - 1 }[e.key];
  if (j === undefined) return;
  e.preventDefault();
  boxes[Math.max(0, Math.min(boxes.length - 1, j))].focus();
});

clearBtn.addEventListener('click', () => {
  const before = rects();
  [...order].reverse().forEach((key, i) => {
    const el = tower.querySelector('[data-key="' + key + '"]:not(.bkp-addons-ghost)');
    ghost(el, i);
    el.remove();
    boxes.find((b) => b.dataset.key === key).checked = false;
  });
  order.length = 0;
  flip(before, null);
  summarise('Cleared every add-on.');
});

root.querySelector('.bkp-addons-cta').addEventListener('click', () => {
  ctaText.textContent = 'STACK SAVED — $' + totalEl.textContent + '/MO';
  live.textContent = 'Trial started with ' + (order.length + 1) + ' modules.';
  if (!reduce.matches) tower.animate([{ transform: 'none' }, { transform: 'scale(1.03, .94)' }, { transform: 'none' }], { duration: 320, easing: 'cubic-bezier(.3,1.6,.5,1)' });
});

/* Initial stack from the pre-checked tiles, in tile order. */
boxes.filter((b) => b.checked).forEach((b) => { order.push(b.dataset.key); tower.append(blockFor(b)); });
summarise('');
live.textContent = '';

