.bkp-enterprise {
  /* re-theme: override these four */
  --bkp-enterprise-bg: oklch(22.5% 0.035 165);
  --bkp-enterprise-ink: oklch(94% 0.018 95);
  --bkp-enterprise-brass: oklch(80% 0.11 84);
  --bkp-enterprise-card: oklch(26.5% 0.038 165);

  --bkp-enterprise-muted: color-mix(in oklch, var(--bkp-enterprise-ink) 62%, var(--bkp-enterprise-bg));
  --bkp-enterprise-faint: color-mix(in oklch, var(--bkp-enterprise-ink) 36%, var(--bkp-enterprise-bg));
  --bkp-enterprise-line: color-mix(in oklch, var(--bkp-enterprise-ink) 12%, transparent);
  --bkp-enterprise-line-2: color-mix(in oklch, var(--bkp-enterprise-ink) 22%, transparent);
  --bkp-enterprise-glow: color-mix(in oklch, var(--bkp-enterprise-brass) 24%, transparent);
  --bkp-enterprise-free: color-mix(in oklch, var(--bkp-enterprise-brass) 30%, oklch(82% 0.09 165));
  --bkp-enterprise-out: cubic-bezier(.16, 1, .3, 1);
  --bkp-enterprise-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(60% 70% at 100% 0%, color-mix(in oklch, var(--bkp-enterprise-brass) 10%, transparent), transparent 70%),
    repeating-linear-gradient(90deg, transparent 0 79px, color-mix(in oklch, var(--bkp-enterprise-ink) 3.5%, transparent) 79px 80px),
    var(--bkp-enterprise-bg);
  color: var(--bkp-enterprise-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, dl, dd, dt) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button, input, select) { font: inherit; color: inherit; }
}
.bkp-enterprise-in {
  display: grid; grid-template-columns: minmax(0, 1fr); gap: clamp(28px, 4cqi, 56px);
  max-width: 1180px; margin-inline: auto; padding: clamp(40px, 6.5cqi, 88px) clamp(16px, 4cqi, 48px);
}
@container (width >= 900px) { .bkp-enterprise-in { grid-template-columns: minmax(0, 1.08fr) minmax(380px, 1fr); align-items: start; } }
.bkp-enterprise-k { font-size: 11px; font-weight: 650; letter-spacing: .18em; text-transform: uppercase; color: var(--bkp-enterprise-brass); }

/* ---------- pitch ---------- */
.bkp-enterprise-pitch { display: grid; gap: 18px; align-content: start; }
.bkp-enterprise-brand {
  display: flex; align-items: center; gap: 9px; font-weight: 700; letter-spacing: -.01em;
  & svg { width: 24px; height: 24px; fill: none; stroke: var(--bkp-enterprise-brass); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & span { padding: 3px 9px; border-radius: 99px; box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line-2); font-size: 11px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--bkp-enterprise-brass); }
}
.bkp-enterprise-title { max-width: 14ch; font-size: clamp(36px, 5.4cqi, 66px); font-weight: 600; line-height: .98; letter-spacing: -.04em; text-wrap: balance; }
.bkp-enterprise-lede { max-width: 54ch; color: var(--bkp-enterprise-muted); font-size: clamp(15px, 1.4cqi, 17px); text-wrap: pretty;
  & b { color: var(--bkp-enterprise-ink); font-weight: 600; font-variant-numeric: tabular-nums; }
}
.bkp-enterprise-incl {
  display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px 22px; margin-top: 4px;
  & li { display: flex; align-items: center; gap: 11px; font-size: 14.5px;
    @starting-style { opacity: 0; translate: 0 8px; }
    transition: opacity .6s var(--bkp-enterprise-out) calc(var(--i) * 60ms), translate .8s var(--bkp-enterprise-out) calc(var(--i) * 60ms); }
  & svg { flex: none; width: 20px; height: 20px; fill: none; stroke: var(--bkp-enterprise-brass); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
}
@container (width >= 560px) { .bkp-enterprise-incl { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.bkp-enterprise-proof {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); margin-top: 10px; border-block: 1px solid var(--bkp-enterprise-line);
  & div { padding: 16px 14px 14px 0; }
  & div + div { padding-left: 14px; border-left: 1px solid var(--bkp-enterprise-line); }
  & dt { font-size: 12px; line-height: 1.3; color: var(--bkp-enterprise-muted); text-wrap: balance; }
  & dd { margin-top: 6px; font-size: clamp(24px, 3cqi, 34px); font-weight: 600; letter-spacing: -.03em; line-height: 1; font-variant-numeric: tabular-nums; }
  & small { margin-left: 2px; font-size: .5em; font-weight: 500; letter-spacing: 0; color: var(--bkp-enterprise-brass); }
}
.bkp-enterprise-logos {
  display: flex; flex-wrap: wrap; gap: 10px 26px; margin-top: 2px;
  & li { display: flex; align-items: center; gap: 7px; font-weight: 650; font-size: 14px; letter-spacing: -.01em; color: var(--bkp-enterprise-faint); }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}

/* ---------- booking card ---------- */
.bkp-enterprise-book {
  position: relative; display: grid; border-radius: 22px; background: var(--bkp-enterprise-card);
  box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line-2), 0 40px 80px -40px oklch(0% 0 0 / .6);
}
.bkp-enterprise-view { grid-area: 1 / 1; display: grid; align-content: start; gap: 12px; padding: clamp(20px, 2.6cqi, 30px); &[hidden] { display: none; } }
.bkp-enterprise-who {
  display: flex; align-items: center; gap: 12px; padding-bottom: 16px; border-bottom: 1px solid var(--bkp-enterprise-line);
  & p { display: grid; line-height: 1.3; }
  & b { font-size: 16.5px; font-weight: 650; letter-spacing: -.01em; }
  & span { font-size: 13px; color: var(--bkp-enterprise-muted); }
}
.bkp-enterprise-face {
  flex: none; display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%;
  background: radial-gradient(circle at 30% 25%, color-mix(in oklch, var(--bkp-enterprise-brass) 70%, white), var(--bkp-enterprise-brass) 60%, color-mix(in oklch, var(--bkp-enterprise-brass) 60%, var(--bkp-enterprise-bg)));
  color: var(--bkp-enterprise-bg); font-size: 14px; font-weight: 750; letter-spacing: .02em;
  box-shadow: 0 0 0 3px var(--bkp-enterprise-card), 0 0 0 4px var(--bkp-enterprise-line-2);
}
.bkp-enterprise-step {
  display: flex; align-items: center; gap: 8px; margin-top: 6px; font-size: 13px; font-weight: 600;
  & i { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; font: 700 11px/1 ui-monospace, Menlo, monospace; font-style: normal; box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line-2); color: var(--bkp-enterprise-brass); }
}
.bkp-enterprise-tz { margin-left: auto; font-weight: 400; font-size: 12px; color: var(--bkp-enterprise-muted); }

.bkp-enterprise-days { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
.bkp-enterprise-day {
  display: grid; justify-items: center; gap: 1px; padding: 9px 2px 8px; border: 0; border-radius: 12px; cursor: pointer;
  background: color-mix(in oklch, var(--bkp-enterprise-ink) 5%, transparent); box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line);
  transition: background-color .25s, box-shadow .25s, color .25s, transform .2s var(--bkp-enterprise-out);
  & small { font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--bkp-enterprise-muted); }
  & b { font-size: 20px; font-weight: 650; line-height: 1.1; font-variant-numeric: tabular-nums; }
  & em { font-style: normal; font-size: 10.5px; color: var(--bkp-enterprise-faint); }
  &:hover { background: color-mix(in oklch, var(--bkp-enterprise-ink) 9%, transparent); }
  &:active { transform: scale(.96); }
  &[aria-checked="true"] { background: var(--bkp-enterprise-brass); color: var(--bkp-enterprise-bg); box-shadow: none;
    & :is(small, em) { color: color-mix(in oklch, var(--bkp-enterprise-bg) 70%, var(--bkp-enterprise-brass)); } }
  &:focus-visible { outline: 2px solid var(--bkp-enterprise-brass); outline-offset: 2px; }
}
.bkp-enterprise-slots { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.bkp-enterprise-slot {
  position: relative; padding: 9px 4px; border: 0; border-radius: 10px; cursor: pointer; font: 500 13.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  background: transparent; box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line-2);
  transition: background-color .2s, box-shadow .2s, color .2s, opacity .3s;
  @starting-style { opacity: 0; transform: translateY(6px); }
  transition-property: background-color, box-shadow, color, opacity, transform; transition-duration: .2s, .2s, .2s, .45s, .6s; transition-timing-function: ease, ease, ease, var(--bkp-enterprise-out), var(--bkp-enterprise-spring);
  transition-delay: 0s, 0s, 0s, calc(var(--i) * 28ms), calc(var(--i) * 28ms);
  &::before { content: ""; position: absolute; top: 6px; right: 6px; width: 5px; height: 5px; border-radius: 50%; background: var(--bkp-enterprise-free); }
  &:hover:not([aria-disabled="true"]) { box-shadow: inset 0 0 0 1px var(--bkp-enterprise-brass); }
  &[aria-checked="true"] { background: var(--bkp-enterprise-ink); color: var(--bkp-enterprise-bg); box-shadow: none; &::before { background: var(--bkp-enterprise-brass); } }
  &[aria-disabled="true"] { cursor: not-allowed; color: var(--bkp-enterprise-faint); text-decoration: line-through; text-decoration-color: var(--bkp-enterprise-line-2); box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line); &::before { display: none; } }
  &:focus-visible { outline: 2px solid var(--bkp-enterprise-brass); outline-offset: 2px; }
}

.bkp-enterprise-form { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 8px; }
.bkp-enterprise-email, .bkp-enterprise-size {
  min-width: 0; height: 44px; padding: 0 12px; border: 0; border-radius: 10px; background: color-mix(in oklch, var(--bkp-enterprise-bg) 55%, var(--bkp-enterprise-card));
  box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line-2); font-size: 14px; accent-color: var(--bkp-enterprise-brass); color-scheme: dark;
  transition: box-shadow .2s;
  &:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--bkp-enterprise-brass), 0 0 0 4px var(--bkp-enterprise-glow); }
  &::placeholder { color: var(--bkp-enterprise-faint); }
  &[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px oklch(70% 0.16 30); }
}
.bkp-enterprise-go {
  grid-column: 1 / -1; display: flex; align-items: center; justify-content: center; gap: 8px; height: 48px; border: 0; border-radius: 12px; cursor: pointer;
  background: var(--bkp-enterprise-brass); color: var(--bkp-enterprise-bg); font-weight: 650;
  transition: transform .2s var(--bkp-enterprise-out), box-shadow .3s, background-color .2s;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: transform .4s var(--bkp-enterprise-spring); }
  &:hover { box-shadow: 0 14px 30px -14px var(--bkp-enterprise-brass); & svg { transform: translateX(3px); } }
  &:active { transform: scale(.985); }
  &:focus-visible { outline: 2px solid var(--bkp-enterprise-ink); outline-offset: 3px; }
}
.bkp-enterprise-err { grid-column: 1 / -1; min-height: 1.2em; font-size: 12.5px; color: oklch(78% 0.13 40); }

/* ---------- confirmation ticket ---------- */
.bkp-enterprise-ticket {
  gap: 10px; outline: none;
  background:
    radial-gradient(circle at 0 62%, var(--bkp-enterprise-bg) 11px, transparent 12px),
    radial-gradient(circle at 100% 62%, var(--bkp-enterprise-bg) 11px, transparent 12px);
}
.bkp-enterprise-done-t { margin-top: 6px; font-size: clamp(28px, 3.4cqi, 38px); font-weight: 600; letter-spacing: -.03em; line-height: 1.05; text-wrap: balance; }
.bkp-enterprise-time { font: 500 20px/1.2 ui-monospace, Menlo, monospace; color: var(--bkp-enterprise-brass); font-variant-numeric: tabular-nums; }
.bkp-enterprise-facts {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px 16px; margin-top: 14px; padding-top: 18px; border-top: 1.5px dashed var(--bkp-enterprise-line-2);
  & dt { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--bkp-enterprise-muted); }
  & dd { margin-top: 3px; font-size: 14.5px; font-weight: 550; overflow-wrap: anywhere; }
}
.bkp-enterprise-agenda { margin-top: 10px; padding: 14px; border-radius: 12px; background: color-mix(in oklch, var(--bkp-enterprise-brass) 10%, transparent); font-size: 14px; color: var(--bkp-enterprise-muted); text-wrap: pretty; }
.bkp-enterprise-back {
  justify-self: start; display: inline-flex; align-items: center; gap: 8px; margin-top: 6px; padding: 10px 14px 10px 10px; border: 0; border-radius: 10px; cursor: pointer;
  background: transparent; box-shadow: inset 0 0 0 1px var(--bkp-enterprise-line-2); font-size: 14px; font-weight: 600;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { box-shadow: inset 0 0 0 1px var(--bkp-enterprise-brass); }
  &:focus-visible { outline: 2px solid var(--bkp-enterprise-brass); outline-offset: 2px; }
}

@container (width < 520px) {
  .bkp-enterprise-slots { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bkp-enterprise-form { grid-template-columns: minmax(0, 1fr); }
  .bkp-enterprise-proof { grid-template-columns: minmax(0, 1fr); & div + div { padding-left: 0; border-left: 0; border-top: 1px solid var(--bkp-enterprise-line); } & div { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 12px 0; } & dd { margin: 0; } }
  .bkp-enterprise-day em { display: none; }
  .bkp-enterprise-tz { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkp-enterprise-incl li, .bkp-enterprise-slot { transition: background-color .2s, box-shadow .2s, color .2s; }
  .bkp-enterprise-go svg, .bkp-enterprise-day { transition: none; }
}

