const TIMES = ['09:00', '09:30', '10:00', '10:30', '11:00', '11:30', '13:00', '13:30', '14:00', '14:30', '15:00', '15:30'];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const daysEl = root.querySelector('.bkp-enterprise-days');
const slotsEl = root.querySelector('.bkp-enterprise-slots');
const pick = root.querySelector('[data-view="pick"]');
const done = root.querySelector('[data-view="done"]');
const form = root.querySelector('.bkp-enterprise-form');
const email = root.querySelector('.bkp-enterprise-email');
const err = root.querySelector('.bkp-enterprise-err');
const zone = (Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC');
const city = zone.split('/').pop().replace(/_/g, ' ');
root.querySelector('[data-tz]').textContent = 'Times in ' + city;

/* The next five weekdays, starting tomorrow. */
const days = [];
for (let d = new Date(); days.length < 5;) {
  d = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1);
  if (d.getDay() % 6) days.push(d);
}
const fmtLong = new Intl.DateTimeFormat('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
const wk = new Intl.DateTimeFormat('en-GB', { weekday: 'short' });
const mo = new Intl.DateTimeFormat('en-GB', { month: 'short' });
/* Deterministic calendar: roughly a third of the slots are already booked. */
const taken = (d, i) => ((d.getDate() * 7 + d.getMonth() * 3 + i * 5) % 9) < 3;

let day = 0, time = null;
daysEl.innerHTML = days.map((d, i) => '<button type="button" class="bkp-enterprise-day" role="radio" aria-checked="false" tabindex="-1" data-i="' + i + '" aria-label="' + fmtLong.format(d) + '">' +
  '<small>' + wk.format(d) + '</small><b>' + d.getDate() + '</b><em>' + mo.format(d) + '</em></button>').join('');
const dayBtns = [...daysEl.children];

function renderSlots() {
  const d = days[day];
  slotsEl.innerHTML = TIMES.map((t, i) => {
    const off = taken(d, i);
    return '<button type="button" class="bkp-enterprise-slot" role="radio" style="--i:' + i + '" data-t="' + t + '" aria-checked="false" tabindex="-1"' +
      (off ? ' aria-disabled="true" aria-label="' + t + ', booked"' : '') + '>' + t + '</button>';
  }).join('');
  /* Keep the chosen time when it is free on the new day, otherwise move to the nearest open slot. */
  if (time) {
    const want = TIMES.indexOf(time);
    const open = slots().filter((s) => !isOff(s)).sort((a, b) => Math.abs(TIMES.indexOf(a.dataset.t) - want) - Math.abs(TIMES.indexOf(b.dataset.t) - want));
    if (open.length && open[0].dataset.t !== time) {
      err.textContent = time + ' is taken that day — moved you to ' + open[0].dataset.t + '.';
      time = open[0].dataset.t;
    } else if (!open.length) time = null;
    else err.textContent = '';
  }
  syncSlots();
}
const slots = () => [...slotsEl.children];
const isOff = (s) => s.getAttribute('aria-disabled') === 'true';
function syncSlots() {
  const list = slots();
  list.forEach((s) => s.setAttribute('aria-checked', String(s.dataset.t === time)));
  const focusable = list.find((s) => s.dataset.t === time) || list.find((s) => !isOff(s));
  list.forEach((s) => { s.tabIndex = s === focusable ? 0 : -1; });
}
function setDay(i, focus) {
  day = i;
  dayBtns.forEach((b, j) => { b.setAttribute('aria-checked', String(j === i)); b.tabIndex = j === i ? 0 : -1; });
  if (focus) dayBtns[i].focus();
  renderSlots();
}

daysEl.addEventListener('click', (e) => { const b = e.target.closest('.bkp-enterprise-day'); if (b) setDay(+b.dataset.i); });
daysEl.addEventListener('keydown', (e) => {
  const n = { ArrowRight: day + 1, ArrowDown: day + 1, ArrowLeft: day - 1, ArrowUp: day - 1, Home: 0, End: days.length - 1 }[e.key];
  if (n === undefined) return;
  e.preventDefault();
  setDay((n + days.length) % days.length, true);
});
slotsEl.addEventListener('click', (e) => {
  const s = e.target.closest('.bkp-enterprise-slot');
  if (!s || isOff(s)) return;
  time = s.dataset.t;
  syncSlots();
  err.textContent = '';
});
/* Two-dimensional arrows that skip booked slots, following the grid's live column count. */
slotsEl.addEventListener('keydown', (e) => {
  const list = slots();
  const i = list.indexOf(document.activeElement);
  if (i < 0) return;
  const cols = getComputedStyle(slotsEl).gridTemplateColumns.split(' ').length;
  const step = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: cols, ArrowUp: -cols }[e.key];
  let j = -1;
  if (step) { for (let k = i + step; k >= 0 && k < list.length; k += step) if (!isOff(list[k])) { j = k; break; } }
  else if (e.key === 'Home') j = list.findIndex((s) => !isOff(s));
  else if (e.key === 'End') j = list.length - 1 - [...list].reverse().findIndex((s) => !isOff(s));
  else return;
  e.preventDefault();
  if (j < 0) return;
  time = list[j].dataset.t;
  syncSlots();
  list[j].focus();
});

function swap(from, to, focusEl) {
  if (reduce.matches) { from.hidden = true; to.hidden = false; focusEl.focus(); return; }
  from.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(-8px)' }], { duration: 180, easing: 'ease-in' }).onfinish = () => {
    if (!root.isConnected) return;
    from.hidden = true;
    to.hidden = false;
    to.animate([{ clipPath: 'inset(0 0 100% 0 round 22px)', opacity: .4 }, { clipPath: 'inset(0 0 0 0 round 22px)', opacity: 1 }], { duration: 620, easing: 'cubic-bezier(.16,1,.3,1)' });
    [...to.children].forEach((c, i) => c.animate([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 520, delay: 120 + i * 45, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' }));
    focusEl.focus({ preventScroll: true });
  };
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const v = email.value.trim();
  if (!time) { err.textContent = 'Pick a time first — open slots have a dot.'; (slots().find((s) => s.tabIndex === 0) || dayBtns[day]).focus(); return; }
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v)) { email.setAttribute('aria-invalid', 'true'); err.textContent = 'Use your work email, like name@company.com.'; email.focus(); return; }
  email.removeAttribute('aria-invalid');
  err.textContent = '';
  const [h, m] = time.split(':').map(Number);
  const end = new Date(2000, 0, 1, h, m + 30);
  done.querySelector('[data-when]').textContent = fmtLong.format(days[day]);
  done.querySelector('[data-time]').textContent = time + ' – ' + String(end.getHours()).padStart(2, '0') + ':' + String(end.getMinutes()).padStart(2, '0');
  done.querySelector('[data-tz2]').textContent = zone.replace(/_/g, ' ');
  done.querySelector('[data-mail]').textContent = v;
  done.querySelector('[data-size]').textContent = root.querySelector('.bkp-enterprise-size').value;
  swap(pick, done, done);
});
email.addEventListener('input', () => { if (email.hasAttribute('aria-invalid')) { email.removeAttribute('aria-invalid'); err.textContent = ''; } });
root.querySelector('.bkp-enterprise-back').addEventListener('click', () => swap(done, pick, slots().find((s) => s.tabIndex === 0) || dayBtns[day]));
done.addEventListener('keydown', (e) => { if (e.key === 'Escape') swap(done, pick, slots().find((s) => s.tabIndex === 0) || dayBtns[day]); });

/* Start on the first day with a sensible open slot already chosen. */
setDay(0);
time = (slots().filter((s) => !isOff(s))[2] || slots().find((s) => !isOff(s))).dataset.t;
syncSlots();

