.bkp-faq {
  /* re-theme: override these four */
  --bkp-faq-paper: oklch(97.6% 0.006 250);
  --bkp-faq-ink: oklch(24% 0.022 265);
  --bkp-faq-marker: oklch(91.5% 0.165 112);
  --bkp-faq-card: oklch(100% 0 0);

  --bkp-faq-muted: color-mix(in oklch, var(--bkp-faq-ink) 60%, var(--bkp-faq-paper));
  --bkp-faq-faint: color-mix(in oklch, var(--bkp-faq-ink) 38%, var(--bkp-faq-paper));
  --bkp-faq-line: color-mix(in oklch, var(--bkp-faq-ink) 11%, transparent);
  --bkp-faq-line-2: color-mix(in oklch, var(--bkp-faq-ink) 20%, transparent);
  --bkp-faq-out: cubic-bezier(.16, 1, .3, 1);
  --bkp-faq-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  container-type: inline-size;
  interpolate-size: allow-keywords;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkp-faq-paper);
  color: var(--bkp-faq-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button, input, output) { font: inherit; color: inherit; }
}
.bkp-faq-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkp-faq-in { position: relative; max-width: 1180px; margin-inline: auto; padding: clamp(36px, 6cqi, 80px) clamp(16px, 4cqi, 48px); }
.bkp-faq-k { font-size: 12px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--bkp-faq-muted); }

/* ---------- header ---------- */
.bkp-faq-head { display: grid; gap: 14px; }
.bkp-faq-brand {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 9px; font-weight: 700;
  & svg { width: 22px; height: 22px; fill: var(--bkp-faq-marker); stroke: var(--bkp-faq-ink); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & span { font-weight: 400; font-size: 13.5px; color: var(--bkp-faq-muted); }
}
.bkp-faq-title {
  max-width: 20ch; font-size: clamp(32px, 5cqi, 60px); font-weight: 650; line-height: 1; letter-spacing: -.04em; text-wrap: balance;
  & span { color: var(--bkp-faq-faint); }
}

/* ---------- layout ---------- */
.bkp-faq-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px; margin-top: clamp(26px, 4cqi, 44px); }
@container (width >= 860px) { .bkp-faq-grid { grid-template-columns: minmax(330px, .82fr) minmax(0, 1.18fr); column-gap: clamp(56px, 8cqi, 104px); align-items: start; } }

/* ---------- plan card ---------- */
.bkp-faq-card {
  position: relative; z-index: 1; display: grid; gap: 16px; padding: clamp(20px, 2.6cqi, 30px); border-radius: 20px; background: var(--bkp-faq-card);
  box-shadow: 0 0 0 1px var(--bkp-faq-line), 0 30px 60px -36px color-mix(in oklch, var(--bkp-faq-ink) 30%, transparent);
}
.bkp-faq-price { display: flex; align-items: flex-end; gap: 12px;
  & b { font-size: clamp(56px, 6.4cqi, 76px); font-weight: 700; line-height: .85; letter-spacing: -.055em; font-variant-numeric: tabular-nums; }
  & span { padding-bottom: 4px; font-size: 13.5px; line-height: 1.3; color: var(--bkp-faq-muted); }
}
.bkp-faq-calc {
  display: grid; grid-template-columns: 1fr auto; grid-template-areas: "l l" "step total"; align-items: center; gap: 8px 12px;
  padding: 14px; border-radius: 14px; background: color-mix(in oklch, var(--bkp-faq-ink) 4%, var(--bkp-faq-card));
}
.bkp-faq-calc-l { grid-area: l; font-size: 12.5px; color: var(--bkp-faq-muted); }
.bkp-faq-stepper {
  grid-area: step; justify-self: start; display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 99px; background: var(--bkp-faq-card); box-shadow: 0 0 0 1px var(--bkp-faq-line-2);
  & button { display: grid; place-items: center; width: 32px; height: 32px; border: 0; border-radius: 50%; background: none; cursor: pointer; transition: background-color .2s, transform .15s var(--bkp-faq-out);
    &:hover { background: color-mix(in oklch, var(--bkp-faq-ink) 7%, transparent); }
    &:active { transform: scale(.9); }
    &:focus-visible { outline: 2px solid var(--bkp-faq-ink); outline-offset: 1px; }
    &:disabled { opacity: .35; cursor: default; }
  }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  & output { min-width: 3ch; text-align: center; font-weight: 700; font-variant-numeric: tabular-nums; }
}
.bkp-faq-calc-t { grid-area: total; text-align: right; font-size: 13px; color: var(--bkp-faq-muted);
  & b { display: block; font-size: 26px; font-weight: 700; letter-spacing: -.03em; line-height: 1; color: var(--bkp-faq-ink); font-variant-numeric: tabular-nums; }
}
.bkp-faq-lines {
  display: grid; gap: 9px; padding-top: 4px;
  & li { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 10px; align-items: center; font-size: 14.5px; }
  & svg { width: 18px; height: 18px; fill: none; stroke: var(--bkp-faq-ink); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
/* the highlighter swipe */
.bkp-faq-mark {
  justify-self: start; padding: 0 3px; margin: 0 -3px; border-radius: 3px;
  background: linear-gradient(100deg, color-mix(in oklch, var(--bkp-faq-marker) 85%, transparent), var(--bkp-faq-marker) 12%, var(--bkp-faq-marker) 92%, color-mix(in oklch, var(--bkp-faq-marker) 70%, transparent)) 0 88% / 0% 64% no-repeat;
  -webkit-box-decoration-break: clone; box-decoration-break: clone;
  transition: background-size .7s var(--bkp-faq-out);
}
.bkp-faq:has(details[data-ref="person"][open]) .bkp-faq-lines [data-ref="person"] .bkp-faq-mark,
.bkp-faq:has(details[data-ref="clients"][open]) .bkp-faq-lines [data-ref="clients"] .bkp-faq-mark,
.bkp-faq:has(details[data-ref="invoice"][open]) .bkp-faq-lines [data-ref="invoice"] .bkp-faq-mark,
.bkp-faq:has(details[data-ref="trial"][open]) .bkp-faq-lines [data-ref="trial"] .bkp-faq-mark,
.bkp-faq:has(details[data-ref="refund"][open]) .bkp-faq-lines [data-ref="refund"] .bkp-faq-mark,
.bkp-faq:has(details[data-ref="export"][open]) .bkp-faq-lines [data-ref="export"] .bkp-faq-mark { background-size: 100% 64%; transition-delay: .18s; }
.bkp-faq-cta {
  display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 50px; padding: 0 18px; border: 0; border-radius: 12px; cursor: pointer;
  background: var(--bkp-faq-ink); color: var(--bkp-faq-paper); font-weight: 650;
  transition: transform .2s var(--bkp-faq-out), box-shadow .25s;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: transform .4s var(--bkp-faq-spring); }
  &:hover { box-shadow: 0 0 0 4px var(--bkp-faq-marker); & svg { transform: translateX(3px); } }
  &:active { transform: scale(.985); }
  &:focus-visible { outline: 2px solid var(--bkp-faq-ink); outline-offset: 3px; }
}
.bkp-faq-fine { font-size: 13px; color: var(--bkp-faq-muted); text-align: center; }

/* ---------- questions ---------- */
.bkp-faq-qa { display: grid; gap: 10px; align-content: start; }
.bkp-faq-search {
  position: relative; display: flex; align-items: center;
  & svg { position: absolute; left: 14px; width: 18px; height: 18px; fill: none; stroke: var(--bkp-faq-muted); stroke-width: 1.8; stroke-linecap: round; pointer-events: none; }
  & kbd { position: absolute; right: 12px; padding: 2px 7px; border-radius: 6px; box-shadow: inset 0 0 0 1px var(--bkp-faq-line-2); font: 500 12px/1.4 ui-monospace, Menlo, monospace; color: var(--bkp-faq-muted); pointer-events: none; }
}
.bkp-faq-input {
  width: 100%; height: 46px; padding: 0 44px 0 42px; border: 0; border-radius: 12px; background: var(--bkp-faq-card); box-shadow: 0 0 0 1px var(--bkp-faq-line-2);
  transition: box-shadow .2s;
  &::placeholder { color: var(--bkp-faq-faint); }
  &:focus-visible { outline: none; box-shadow: 0 0 0 1.5px var(--bkp-faq-ink), 0 0 0 5px var(--bkp-faq-marker); }
  &::-webkit-search-cancel-button { display: none; }
}
.bkp-faq-list { border-top: 1px solid var(--bkp-faq-line-2);
  & details { border-bottom: 1px solid var(--bkp-faq-line-2); }
  & details[hidden] { display: none; }
  & summary {
    display: grid; grid-template-columns: minmax(0, 1fr) 26px; align-items: center; gap: 12px; padding: 17px 2px; cursor: pointer; list-style: none;
    font-size: clamp(15.5px, 1.6cqi, 17.5px); font-weight: 600; letter-spacing: -.012em; border-radius: 6px;
    &::-webkit-details-marker { display: none; }
    &:hover .bkp-faq-q { text-decoration: underline; text-decoration-color: var(--bkp-faq-line-2); text-underline-offset: 4px; }
    &:focus-visible { outline: 2px solid var(--bkp-faq-ink); outline-offset: 2px; }
  }
  & summary i {
    position: relative; width: 26px; height: 26px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--bkp-faq-line-2); transition: background-color .3s, box-shadow .3s, rotate .5s var(--bkp-faq-spring);
    &::before, &::after { content: ""; position: absolute; left: 8px; right: 8px; top: 12.25px; height: 1.5px; border-radius: 2px; background: currentColor; transition: rotate .4s var(--bkp-faq-spring); }
    &::after { rotate: 90deg; }
  }
  & details[open] summary i { background: var(--bkp-faq-marker); box-shadow: none; rotate: 180deg; &::after { rotate: 0deg; } }
  & mark { background: var(--bkp-faq-marker); color: inherit; border-radius: 2px; padding: 0 1px; }
  & details::details-content { block-size: 0; overflow-y: clip; transition: block-size .45s var(--bkp-faq-out), content-visibility .45s allow-discrete; }
  & details[open]::details-content { block-size: auto; }
}
.bkp-faq-a { padding: 0 44px 18px 2px; color: var(--bkp-faq-muted); text-wrap: pretty;
  & p { max-width: 60ch; }
}
.bkp-faq-ref {
  display: flex; align-items: center; gap: 6px; margin-top: 10px; font-size: 13px; color: var(--bkp-faq-ink);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  & span { padding: 0 4px; border-radius: 3px; background: var(--bkp-faq-marker); font-weight: 550; }
}
@container (width >= 860px) { .bkp-faq-ref { display: none; } }
.bkp-faq-list details[open] .bkp-faq-a { animation: bkp-faq-in .5s var(--bkp-faq-out) both; }
@keyframes bkp-faq-in { from { opacity: 0; translate: 0 -6px; } }
.bkp-faq-empty { padding: 18px 2px; color: var(--bkp-faq-muted);
  & button { padding: 0; border: 0; background: none; cursor: pointer; font-weight: 600; color: var(--bkp-faq-ink); text-decoration: underline; text-underline-offset: 3px; }
  & button:focus-visible { outline: 2px solid var(--bkp-faq-ink); outline-offset: 2px; border-radius: 3px; }
}

/* ---------- the wire from answer to plan line (two-column layout only) ---------- */
.bkp-faq-wire {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; z-index: 2; display: none; transition: opacity .25s;
  & path { fill: none; stroke: var(--bkp-faq-ink); stroke-width: 1.5; stroke-linecap: round; }
  & circle { fill: var(--bkp-faq-card); stroke: var(--bkp-faq-ink); stroke-width: 1.5; transform-box: fill-box; transform-origin: center; }
}
@container (width >= 860px) { .bkp-faq-wire { display: block; } }

@media (prefers-reduced-motion: reduce) {
  .bkp-faq-mark { transition: none; }
  .bkp-faq-list details::details-content { transition: none; }
  .bkp-faq-ref {
  display: flex; align-items: center; gap: 6px; margin-top: 10px; font-size: 13px; color: var(--bkp-faq-ink);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  & span { padding: 0 4px; border-radius: 3px; background: var(--bkp-faq-marker); font-weight: 550; }
}
@container (width >= 860px) { .bkp-faq-ref { display: none; } }
.bkp-faq-list details[open] .bkp-faq-a { animation: none; }
  .bkp-faq-list summary i, .bkp-faq-list summary i::before, .bkp-faq-list summary i::after, .bkp-faq-cta svg { transition: none; }
}

