const PRICE = 12;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const inner = root.querySelector('.bkp-faq-in');
const list = root.querySelector('.bkp-faq-list');
const items = [...list.querySelectorAll('details')];
const input = root.querySelector('.bkp-faq-input');
const empty = root.querySelector('.bkp-faq-empty');
const live = root.querySelector('[data-live]');
const wire = root.querySelector('.bkp-faq-wire');
const card = root.querySelector('.bkp-faq-card');
const path = wire.querySelector('path');
const [dotA, dotB] = wire.querySelectorAll('circle');
const uid = Math.random().toString(36).slice(2, 8);
items.forEach((d) => {
  d.name = 'bkp-faq-' + uid;
  d.querySelector('.bkp-faq-q').dataset.text = d.querySelector('.bkp-faq-q').textContent;
  /* In the stacked layout the wire can't reach, so each linked answer quotes its plan line instead. */
  const line = d.dataset.ref && root.querySelector('.bkp-faq-lines [data-ref="' + d.dataset.ref + '"] .bkp-faq-mark');
  if (line) {
    const p = document.createElement('p');
    p.className = 'bkp-faq-ref';
    p.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5.5 12.5 4 4 9-9.5"/></svg>On the plan: <span></span>';
    p.querySelector('span').textContent = line.textContent;
    d.querySelector('.bkp-faq-a').append(p);
  }
});

/* ---------- price stepper ---------- */
let people = 8;
const stepBtns = [...root.querySelectorAll('.bkp-faq-stepper button')];
function setPeople(n) {
  people = Math.max(1, Math.min(500, n));
  root.querySelector('[data-n]').textContent = people;
  const solo = people === 1;
  root.querySelector('[data-total]').textContent = solo ? '$0' : '$' + (people * PRICE).toLocaleString('en');
  root.querySelector('[data-total-note]').textContent = solo ? 'free for one' : 'a month';
  root.querySelector('[data-cta]').textContent = solo ? 'Start free, on your own' : 'Start a 30-day trial for ' + people;
  stepBtns[0].disabled = people <= 1;
}
stepBtns.forEach((b) => b.addEventListener('click', () => setPeople(people + +b.dataset.d)));
const cta = root.querySelector('[data-cta]');
root.querySelector('.bkp-faq-cta').addEventListener('click', () => {
  live.textContent = people === 1 ? 'Free one-person workspace ready.' : 'Trial started for ' + people + ' people, $' + people * PRICE + ' a month after 30 days.';
  cta.textContent = people === 1 ? 'Workspace ready \u2014 check your inbox' : 'Trial started \u2014 check your inbox';
  clearTimeout(cta._t);
  cta._t = setTimeout(() => setPeople(people), 2600);
});

/* ---------- the wire: from the open answer to the plan line it explains ---------- */
let follow = 0, drawn = '';
function place(animate) {
  const open = items.find((d) => d.open && !d.hidden && d.dataset.ref);
  const show = open && getComputedStyle(wire).display !== 'none';
  if (!show) { wire.style.opacity = 0; drawn = ''; return; }
  const box = inner.getBoundingClientRect();
  const mark = root.querySelector('.bkp-faq-lines [data-ref="' + open.dataset.ref + '"] .bkp-faq-mark').getBoundingClientRect();
  const sum = open.querySelector('summary').getBoundingClientRect();
  const edge = card.getBoundingClientRect().right - box.left;
  const x1 = mark.right - box.left + 10, y1 = mark.top + mark.height / 2 - box.top;
  const x2 = sum.left - box.left - 10, y2 = sum.top + sum.height / 2 - box.top;
  /* Run flat to the card's edge, then make the S-bend inside the gutter so the wire never crosses card content. */
  const bend = Math.max(16, (x2 - edge) * 0.5);
  path.setAttribute('d', 'M' + x1 + ' ' + y1 + 'H' + edge + 'C' + (edge + bend) + ' ' + y1 + ' ' + (x2 - bend) + ' ' + y2 + ' ' + x2 + ' ' + y2);
  dotA.setAttribute('cx', x1); dotA.setAttribute('cy', y1);
  dotB.setAttribute('cx', x2); dotB.setAttribute('cy', y2);
  wire.style.opacity = 1;
  if (animate && drawn !== open.dataset.ref && !reduce.matches) {
    const len = path.getTotalLength();
    path.animate([{ strokeDasharray: len, strokeDashoffset: len }, { strokeDasharray: len, strokeDashoffset: 0 }], { duration: 650, delay: 120, easing: 'cubic-bezier(.65,0,.35,1)', fill: 'backwards' });
    dotB.animate([{ opacity: 0, transform: 'scale(0)' }, { opacity: 1, transform: 'none' }], { duration: 300, delay: 700, easing: 'cubic-bezier(.2,1.6,.4,1)', fill: 'backwards' });
  }
  drawn = open.dataset.ref;
}
/* Follow the summaries while the accordion animates its height. */
function track(ms) {
  const until = performance.now() + ms;
  cancelAnimationFrame(follow);
  const tick = (now) => {
    if (!root.isConnected) return;
    place(false);
    if (now < until) follow = requestAnimationFrame(tick);
  };
  follow = requestAnimationFrame(tick);
}
list.addEventListener('toggle', (e) => {
  if (!items.includes(e.target)) return;
  place(e.target.open);
  track(520);
}, true);
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } place(false); });
ro.observe(inner);

/* ---------- search ---------- */
const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function filter() {
  const q = input.value.trim().toLowerCase();
  let shown = 0;
  items.forEach((d) => {
    const qEl = d.querySelector('.bkp-faq-q');
    const text = qEl.dataset.text;
    const hit = !q || (text + ' ' + d.querySelector('.bkp-faq-a').textContent).toLowerCase().includes(q);
    d.hidden = !hit;
    if (hit) shown++;
    const at = q ? text.toLowerCase().indexOf(q) : -1;
    qEl.innerHTML = at < 0 ? esc(text) : esc(text.slice(0, at)) + '<mark>' + esc(text.slice(at, at + q.length)) + '</mark>' + esc(text.slice(at + q.length));
  });
  empty.hidden = shown > 0;
  empty.querySelector('[data-q]').textContent = input.value.trim();
  live.textContent = q ? shown + ' of ' + items.length + ' questions match.' : '';
  place(false);
}
input.addEventListener('input', filter);
const visible = () => items.filter((d) => !d.hidden).map((d) => d.querySelector('summary'));
input.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && input.value) { e.preventDefault(); input.value = ''; filter(); }
  else if (e.key === 'ArrowDown' || e.key === 'Enter') {
    const first = visible()[0];
    if (first) { e.preventDefault(); first.focus(); }
  }
});
root.querySelector('.bkp-faq-clear').addEventListener('click', () => { input.value = ''; filter(); input.focus(); });

/* Arrow keys walk the visible questions; Escape closes the one you're on. */
list.addEventListener('keydown', (e) => {
  const sums = visible();
  const i = sums.indexOf(document.activeElement);
  if (i < 0) return;
  if (e.key === 'Escape') { const d = sums[i].parentElement; if (d.open) { e.preventDefault(); d.open = false; } return; }
  const j = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: sums.length - 1 }[e.key];
  if (j === undefined) return;
  e.preventDefault();
  if (j < 0) { input.focus(); return; }
  sums[Math.min(sums.length - 1, j)].focus();
});

setPeople(people);
requestAnimationFrame(() => { if (!root.isConnected) return; place(true); });
